'use strict';
// 光化学与激发态（/photochem/）的十五个演示。数学都在 pc-models.js（纯函数，tools/photochem-test.mjs 测）。pc.js 用 window.MOLASTRIA_PHOTOCHEM_DEMOS(K, DEMOS) 把它们登记进去。
// 写法同群论的 gt-demos.js：title，kind，intro，sel，ctl，chk，btn，state，autoplay，fps + tick(s)，changed，figs，note，draw(s, 图, 颜色) 返回读数。
// 读数的值按 HTML 放进页面，只放这里自己算出来的数字和固定的文字。
window.MOLASTRIA_PHOTOCHEM_DEMOS = (K, DEMOS) => {
  const M = window.MOLASTRIA_PHOTOCHEM_MODELS;
  const { L, fix, fmt, plot, fit, lin, font, arrow } = K;
  const PI = Math.PI;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const e10 = (v) => 10 ** v;
  const sci = (v, d = 2) => fmt(v, d + 1);
  const time = (t) => (t >= 1 ? `${fix(t, 2)} s` : t >= 1e-3 ? `${fix(t * 1e3, 2)} ms` : t >= 1e-6 ? `${fix(t * 1e6, 2)} μs` : t >= 1e-9 ? `${fix(t * 1e9, 2)} ns` : t >= 1e-12 ? `${fix(t * 1e12, 2)} ps` : `${fix(t * 1e15, 0)} fs`);
  const pc = (v, d = 1) => `${(100 * v).toFixed(d)} %`;
  const nm2cm = (l) => 1e7 / l;

  // ── 1. 吸收：振子强度、跃迁偶极和 Strickler–Berg ───────────────────
  DEMOS.absorb = {
    title: L('一条吸收带里藏着多少信息：振子强度、跃迁偶极和辐射寿命', 'What one absorption band tells you: oscillator strength, transition dipole and radiative lifetime'), kind: 'approx',
    intro: L('吸收谱上一条带的面积（不是峰高）量出跃迁有多“允许”：振子强度 f 和跃迁偶极 μ。同一个跃迁倒过来就是荧光，所以面积也决定了激发态自己发光要多久（Strickler–Berg 关系）。改峰高、峰宽和位置，看这几个数怎么跟着变；溶液浓度和光程决定能透过多少光（Beer–Lambert）。', 'The area of an absorption band (not its height) measures how “allowed” the transition is: the oscillator strength f and the transition dipole μ. The same transition run backwards is fluorescence, so the area also sets how long the excited state takes to emit by itself (the Strickler–Berg relation). Change the height, width and position to see how these numbers move; concentration and path length set how much light gets through (Beer–Lambert).'),
    ctl: [['le', L('峰值摩尔吸光系数 log₁₀ ε_max（M⁻¹ cm⁻¹）', 'Peak molar absorptivity log₁₀ ε_max (M⁻¹ cm⁻¹)'), -2, 5.5, 0.01, 5.06, (v) => `ε = ${fmt(e10(v), 3)}`], ['w', L('半高宽 Δν̃（cm⁻¹）', 'Full width Δν̃ (cm⁻¹)'), 300, 8000, 10, 1500, (v) => `${v.toFixed(0)} cm⁻¹`], ['lam', L('峰位 λ_max（nm）', 'Peak λ_max (nm)'), 200, 800, 1, 530, (v) => `${v.toFixed(0)} nm`], ['n', L('溶剂折射率 n', 'Solvent refractive index n'), 1, 1.7, 0.01, 1.36, (v) => v.toFixed(2)], ['phi', L('荧光量子产率 Φ_F', 'Fluorescence quantum yield Φ_F'), 0, 1, 0.01, 0.95, (v) => v.toFixed(2)], ['lc', L('浓度 log₁₀ c（M）', 'Concentration log₁₀ c (M)'), -8, -1, 0.01, -5.3, (v) => `${fmt(e10(v), 2)} M`]],
    btn: [[L('强的 π→π*（像罗丹明染料）', 'Strong π→π* (rhodamine-like dye)'), { le: 5.06, w: 1500, lam: 530, n: 1.36, phi: 0.95 }], [L('弱的 n→π*（像丙酮）', 'Weak n→π* (acetone-like)'), { le: Math.log10(15), w: 5000, lam: 275, n: 1.36, phi: 0.001 }], [L('自旋禁阻的 S₀→T₁', 'Spin-forbidden S₀→T₁'), { le: -1, w: 2000, lam: 480, n: 1.4, phi: 0.5 }]],
    figs: [[0.5, L('摩尔吸光系数 ε(λ)，阴影是带的面积。谱带在波数上是高斯形，换到波长上略有不对称。', 'Molar absorptivity ε(λ); the shaded area is the band area. The band is Gaussian in wavenumber, so slightly asymmetric in wavelength.')]],
    note: L('f = 4.319 × 10⁻⁹ ∫ε dν̃（ε 以 M⁻¹ cm⁻¹、ν̃ 以 cm⁻¹ 计），f = 4.702 × 10⁻⁷ ν̃ |μ|²（μ 以德拜计），Strickler–Berg 简化式 k_r ≈ 2.880 × 10⁻⁹ n² ν̃² ∫ε dν̃（s⁻¹），荧光寿命 τ_F = Φ_F / k_r。简化式假设吸收和发射的谱形镜像、激发态几何不变；荧光和吸收的 Stokes 位移大或者跃迁很弱（例如自旋禁阻）时，误差可以到好几倍。预设的数字是大致的量级，不是某个分子的测量值。', 'f = 4.319 × 10⁻⁹ ∫ε dν̃ (ε in M⁻¹ cm⁻¹, ν̃ in cm⁻¹), f = 4.702 × 10⁻⁷ ν̃ |μ|² (μ in debye), the simplified Strickler–Berg relation k_r ≈ 2.880 × 10⁻⁹ n² ν̃² ∫ε dν̃ (s⁻¹), and the fluorescence lifetime τ_F = Φ_F / k_r. The simplified form assumes mirror-image absorption and emission and no change of geometry; with a large Stokes shift or a very weak (e.g. spin-forbidden) transition it can be off by several times. The presets are rough orders of magnitude, not measurements of particular molecules.'),
    draw(s, [cv], c) {
      const eps = e10(s.le), nu0 = nm2cm(s.lam), lo = Math.max(150, 1e7 / (nu0 + 3 * s.w)), hi = 1e7 / Math.max(1000, nu0 - 3 * s.w);
      const xs = lin(lo, hi, 500), ys = xs.map((l) => eps * M.gauss(nm2cm(l), nu0, s.w));
      plot(cv, { x: [lo, hi], y: [0, eps * 1.12], xl: L('波长 λ（nm）', 'wavelength λ (nm)'), yl: 'ε (M⁻¹ cm⁻¹)', yf: (t) => fmt(t, 2), series: [{ xs, ys, color: c.accent, width: 2.2, fill: true }], marks: [{ x: s.lam, color: c.gold }] });
      const f = M.oscStrength(eps, s.w), mu = M.dipoleD(f, nu0), kr = M.stricklerBerg(eps, s.w, nu0, s.n), A = M.absorbance(eps, e10(s.lc));
      return [[L('带的面积 ∫ε dν̃', 'Band area ∫ε dν̃'), `${sci(M.bandArea(eps, s.w))} M⁻¹ cm⁻²`], [L('振子强度 f', 'Oscillator strength f'), fmt(f, 3), true], [L('跃迁偶极 |μ|', 'Transition dipole |μ|'), `${fmt(mu, 3)} D`], [L('辐射速率 k_r（Strickler–Berg）', 'Radiative rate k_r (Strickler–Berg)'), `${sci(kr)} s⁻¹`], [L('自然寿命 τ₀ = 1/k_r', 'Natural lifetime τ₀ = 1/k_r'), time(1 / kr)], [L('荧光寿命 τ_F = Φ_F τ₀', 'Fluorescence lifetime τ_F = Φ_F τ₀'), s.phi > 0 ? time(s.phi / kr) : '—'], [L('1 cm 光程的吸光度 A', 'Absorbance A over 1 cm'), fmt(A, 3)], [L('透过的光', 'Light transmitted'), pc(M.transmit(A), 1)]];
    },
  };

  // ── 2. Jablonski 图 ───────────────────────────────────────────────
  DEMOS.jablonski = {
    title: L('Jablonski 图：一个激发态的五条出路，箭头粗细按量子产率画', 'The Jablonski diagram: five ways out of an excited state, arrows drawn as thick as their quantum yields'), kind: 'exact',
    intro: L('分子吸收一个光子到了 S₁，接下来是几个过程在赛跑：荧光（k_F）、内转换回基态（k_IC）、系间窜越到三重态（k_ISC）；到了 T₁ 又有磷光（k_P）和无辐射失活（k_T）。每条路的份额就是它的速率除以总速率。拖动速率常数（对数刻度），看量子产率、寿命和布居怎么变；“猝灭剂”同时加快 S₁ 和 T₁ 的失活，长寿命的 T₁ 最怕它。', 'A molecule absorbs a photon and lands in S₁; then several processes race: fluorescence (k_F), internal conversion to the ground state (k_IC) and intersystem crossing to the triplet (k_ISC); from T₁ come phosphorescence (k_P) and radiationless decay (k_T). Each pathway’s share is its rate over the total rate. Drag the rate constants (log scale) to watch quantum yields, lifetimes and populations; a “quencher” speeds up the decay of both S₁ and T₁, and the long-lived T₁ suffers most.'),
    ctl: [['F', 'log₁₀ k_F (s⁻¹)', 5, 10, 0.01, Math.log10(6e7), (v) => sci(e10(v))], ['IC', 'log₁₀ k_IC (s⁻¹)', 4, 12, 0.01, 6, (v) => sci(e10(v))], ['ISC', 'log₁₀ k_ISC (s⁻¹)', 4, 12, 0.01, Math.log10(1.4e8), (v) => sci(e10(v))], ['P', 'log₁₀ k_P (s⁻¹)', -1, 5, 0.01, 1, (v) => sci(e10(v))], ['TNR', 'log₁₀ k_T (s⁻¹)', -1, 7, 0.01, 3, (v) => sci(e10(v))], ['q', L('猝灭 log₁₀ k_q[Q]（s⁻¹）', 'Quenching log₁₀ k_q[Q] (s⁻¹)'), 0, 10, 0.01, 0, (v) => (v <= 0.001 ? L('没有', 'none') : sci(e10(v)))]],
    btn: [[L('像蒽（荧光加三重态）', 'Anthracene-like (fluorescence plus triplet)'), { F: Math.log10(6e7), IC: 6, ISC: Math.log10(1.4e8), P: 1, TNR: 3, q: 0 }], [L('像二苯甲酮（几乎全部窜越）', 'Benzophenone-like (nearly all crossing)'), { F: 6, IC: 6, ISC: 11, P: 2.2, TNR: 4, q: 0 }], [L('同上，溶液里通了空气', 'Same, in air-saturated solution'), { F: 6, IC: 6, ISC: 11, P: 2.2, TNR: 4, q: Math.log10(2e7) }], [L('高效荧光染料', 'Efficient fluorescent dye'), { F: Math.log10(2.4e8), IC: 7, ISC: 5.5, P: 1, TNR: 4, q: 0 }]],
    figs: [[0.62, L('能级和路径：箭头粗细正比于量子产率，直线是发光，波浪线是无辐射跃迁。', 'Levels and pathways: arrow thickness is proportional to quantum yield; straight lines emit light, wavy lines are radiationless.')], [0.45, L('脉冲激发后 S₁ 和 T₁ 的布居（双对数坐标）。', 'S₁ and T₁ populations after a pulse (log–log).')]],
    note: L('一阶动力学：S₁ 的总速率 k_S = k_F + k_IC + k_ISC + k_q[Q]，T₁ 的 k_T,tot = k_P + k_T + k_q[Q]；Φ_F = k_F/k_S，Φ_ISC = k_ISC/k_S，Φ_P = Φ_ISC k_P/k_T,tot。T₁(t) = k_ISC (e^{−k_S t} − e^{−k_T,tot t}) / (k_T,tot − k_S)。真实分子还有 S₁ ← T₁ 的反向窜越（第八章的 TADF）、高激发态和三重态–三重态湮灭，这里都没有。预设只是量级。', 'First-order kinetics: S₁ decays with k_S = k_F + k_IC + k_ISC + k_q[Q], T₁ with k_T,tot = k_P + k_T + k_q[Q]; Φ_F = k_F/k_S, Φ_ISC = k_ISC/k_S, Φ_P = Φ_ISC k_P/k_T,tot. T₁(t) = k_ISC (e^{−k_S t} − e^{−k_T,tot t}) / (k_T,tot − k_S). Real molecules also have reverse crossing T₁ → S₁ (TADF, chapter 8), higher states and triplet–triplet annihilation, none of which is here. The presets are orders of magnitude only.'),
    draw(s, [cv, cv2], c) {
      const k = { F: e10(s.F), IC: e10(s.IC), ISC: e10(s.ISC), P: e10(s.P), TNR: e10(s.TNR), q: s.q > 0.001 ? e10(s.q) : 0 }, J = M.jablonski(k);
      const { ctx, w, h } = fit(cv), y0 = h * 0.86, yS = h * 0.24, yT = h * 0.46, xS = w * 0.12, xT = w * 0.6, lw = w * 0.26;
      const lvl = (x, y, lab) => { ctx.strokeStyle = c.ink; ctx.lineWidth = 2.2; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + lw, y); ctx.stroke(); ctx.strokeStyle = c.line; ctx.lineWidth = 1; for (let i = 1; i <= 3; i++) { ctx.beginPath(); ctx.moveTo(x, y - i * h * 0.025); ctx.lineTo(x + lw, y - i * h * 0.025); ctx.stroke(); } ctx.fillStyle = c.ink; ctx.font = font(13, 700); ctx.textAlign = 'right'; ctx.fillText(lab, x - 6, y + 4); };
      lvl(xS, y0, 'S₀'); lvl(xS, yS, 'S₁'); lvl(xT, yT, 'T₁');
      ctx.strokeStyle = c.line; ctx.beginPath(); ctx.moveTo(xT, y0); ctx.lineTo(xT + lw, y0); ctx.stroke();
      const width = (phi) => 0.8 + 9 * Math.sqrt(clamp(phi, 0, 1));
      const wavy = (x0, y0_, x1, y1, col, wd) => { const n = 60, dx = x1 - x0, dy = y1 - y0_, len = Math.hypot(dx, dy), ux = -dy / len, uy = dx / len; ctx.strokeStyle = col; ctx.lineWidth = wd; ctx.beginPath(); for (let i = 0; i <= n; i++) { const f = i / n, a = Math.sin(f * len / 7) * 4 * (f < 0.9 ? 1 : 0); const x = x0 + dx * f + ux * a, y = y0_ + dy * f + uy * a; if (i) ctx.lineTo(x, y); else ctx.moveTo(x, y); } ctx.stroke(); arrow(ctx, x0 + dx * 0.93, y0_ + dy * 0.93, x1, y1, col, wd); };
      const lab = (t, x, y, col, al = 'center') => { ctx.fillStyle = col; ctx.font = font(11.5, 600); ctx.textAlign = al; ctx.fillText(t, x, y); };
      arrow(ctx, xS + lw * 0.12, y0, xS + lw * 0.12, yS - h * 0.075, c.info, 3); lab(L('吸收', 'abs.'), xS + lw * 0.12, y0 + 16, c.info);
      arrow(ctx, xS + lw * 0.42, yS, xS + lw * 0.42, y0, c.ok, width(J.phiF)); lab(`F ${pc(J.phiF, 0)}`, xS + lw * 0.42, y0 + 16, c.ok);
      wavy(xS + lw * 0.8, yS, xS + lw * 0.8, y0, c.muted, width(J.phiIC)); lab(`IC ${pc(J.phiIC, 0)}`, xS + lw * 0.8, y0 + 16, c.muted);
      wavy(xS + lw, yS + 4, xT + 4, yT - 4, c.violet || c.info, width(J.phiISC)); lab(`ISC ${pc(J.phiISC, 0)}`, (xS + lw + xT) / 2, (yS + yT) / 2 - 12, c.violet || c.info);
      arrow(ctx, xT + lw * 0.3, yT, xT + lw * 0.3, y0, c.danger, width(J.phiP)); lab(`P ${pc(J.phiP, 1)}`, xT + lw * 0.3, y0 + 16, c.danger);
      wavy(xT + lw * 0.75, yT, xT + lw * 0.75, y0, c.muted, width(J.phiTNR)); lab(`k_T ${pc(J.phiTNR, 0)}`, xT + lw * 0.75, y0 + 16, c.muted);
      if (k.q) lab(L(`猝灭：S₁ ${pc(J.phiQS, 0)}，T₁ ${pc(J.phiQT, 0)}`, `quenched: S₁ ${pc(J.phiQS, 0)}, T₁ ${pc(J.phiQT, 0)}`), xT + lw, yT - h * 0.12, c.warn, 'right');
      // 布居
      const t0 = Math.log10(Math.min(J.tauS, J.tauT)) - 2, t1 = Math.log10(Math.max(J.tauS, J.tauT)) + 1.3, ts = lin(t0, t1, 400).map(e10);
      const Sy = ts.map(J.S), Ty = ts.map(J.T), lo = -4;
      plot(cv2, { logx: true, logy: true, x: [t0, t1], y: [lo, 0.1], xl: L('时间 t（s）', 'time t (s)'), yl: L('布居', 'population'), series: [{ xs: ts, ys: Sy.map((v) => Math.max(v, 1e-6)), color: c.ok, width: 2.2, label: 'S₁' }, { xs: ts, ys: Ty.map((v) => Math.max(v, 1e-6)), color: c.danger, width: 2.2, label: 'T₁' }] });
      return [[L('荧光量子产率 Φ_F', 'Fluorescence yield Φ_F'), fix(J.phiF, 3), true], [L('系间窜越 Φ_ISC', 'Intersystem crossing Φ_ISC'), fix(J.phiISC, 3)], [L('磷光量子产率 Φ_P', 'Phosphorescence yield Φ_P'), fmt(J.phiP, 3)], [L('S₁ 寿命 τ_S', 'S₁ lifetime τ_S'), time(J.tauS)], [L('T₁ 寿命 τ_T', 'T₁ lifetime τ_T'), time(J.tauT)], [L('自然寿命 1/k_F', 'Natural lifetime 1/k_F'), time(J.tau0)]];
    },
  };

  // ── 3. Franck–Condon 谱 ───────────────────────────────────────────
  DEMOS.fc = {
    title: L('Franck–Condon：吸收和荧光的振动结构，和为什么它们互为镜像', 'Franck–Condon: the vibrational structure of absorption and fluorescence, and why they mirror each other'), kind: 'exact',
    intro: L('电子跳得比原子核动得快得多，所以跃迁是“竖直”的：核的位置不变，落到上面势能曲线的哪个振动能级，按波函数重叠的平方（Franck–Condon 因子）分配。上下两条势能曲线一样宽、只是错开时，这些因子是 Poisson 分布，只由 Huang–Rhys 因子 S 决定。S 小，0–0 带最强；S 大，强度跑到高振动能级上。吸收往高能那边排，荧光往低能那边排，两者对 0–0 带成镜像；两条曲线宽窄不同时，镜像就破了。', 'Electrons jump much faster than nuclei move, so the transition is “vertical”: the nuclei stay put, and which vibrational level of the upper curve is reached is shared out by the squared wavefunction overlaps (Franck–Condon factors). For two equally wide curves that are merely shifted, the factors form a Poisson distribution set by the Huang–Rhys factor S alone. Small S: the 0–0 band is strongest; large S: intensity moves to high vibrational levels. Absorption stacks to higher energy and fluorescence to lower, mirror images about the 0–0 band; when the two curves differ in width, the mirror breaks.'),
    ctl: [['S', L('Huang–Rhys 因子 S', 'Huang–Rhys factor S'), 0, 5, 0.01, 1.1, (v) => v.toFixed(2)], ['hw', L('振动量子 ħω（cm⁻¹）', 'Vibrational quantum ħω (cm⁻¹)'), 200, 2500, 10, 1400, (v) => `${v.toFixed(0)} cm⁻¹`], ['r', L('上下频率比 ω′/ω″', 'Frequency ratio ω′/ω″'), 0.6, 1.5, 0.01, 1, (v) => v.toFixed(2)], ['E00', L('0–0 跃迁（cm⁻¹）', '0–0 transition (cm⁻¹)'), 12000, 40000, 50, 26000, (v) => `${v.toFixed(0)} cm⁻¹ · ${(1e7 / v).toFixed(0)} nm`], ['fw', L('每条振动带的展宽（cm⁻¹）', 'Width of each vibronic band (cm⁻¹)'), 60, 2500, 10, 500, (v) => `${v.toFixed(0)} cm⁻¹`]],
    chk: [['stick', L('画出每条振动带', 'Show each vibronic line'), true]],
    btn: [[L('刚性的芳烃（S 小）', 'Rigid aromatic (small S)'), { S: 0.8, hw: 1400, r: 1, fw: 350 }], [L('像蒽', 'Anthracene-like'), { S: 1.1, hw: 1400, r: 1, E00: 26400, fw: 500 }], [L('几何变化大（S = 4）', 'Large geometry change (S = 4)'), { S: 4, hw: 1200, r: 1, fw: 700 }], [L('上面的势软一些', 'Softer upper curve'), { S: 1.5, hw: 1400, r: 0.75, fw: 400 }]],
    figs: [[0.52, L('吸收（蓝，按 ν 加权）和荧光（金，按 ν³ 加权），各自归一。竖线是每条振动带的 Franck–Condon 因子。', 'Absorption (blue, weighted by ν) and fluorescence (gold, weighted by ν³), each normalised. Vertical lines are the Franck–Condon factors of the vibronic bands.')]],
    note: L('单个振动模、T = 0（只从 v = 0 出发）。频率比为 1 时 FC 因子是 e^{−S}Sᵛ/v!；不为 1 时在细格子上数值积分谐振子波函数的重叠（总和等于 1 是一个检验）。吸收的振动间隔是上面的势的 ħω′，荧光的是下面的 ħω″。Stokes 位移这里只来自这一个模（2Sħω 是两条谱的重心之差），溶剂的贡献要另外加。真实的分子有几十个模和热布居。', 'One vibrational mode, T = 0 (starting from v = 0 only). With frequency ratio 1 the FC factors are e^{−S}Sᵛ/v!; otherwise the harmonic-oscillator overlaps are integrated numerically on a fine grid (that they sum to 1 is a check). Absorption is spaced by the upper curve’s ħω′, fluorescence by the lower curve’s ħω″. The Stokes shift here comes from this one mode only (2Sħω is the distance between the centroids of the two spectra); solvent adds more. Real molecules have dozens of modes and thermal populations.'),
    draw(s, [cv], c) {
      const nmax = 24, d = Math.sqrt(2 * s.S), fc = Math.abs(s.r - 1) < 1e-6 ? (() => { const p = Array.from({ length: nmax + 1 }, (_, v) => M.poisson(s.S, v)); return { from0: p, to0: p }; })() : M.fcFactors(1, s.r, d, nmax, 1600);
      const hwU = s.hw * s.r, lo = s.E00 - 7 * s.hw, hi = s.E00 + 7 * hwU, xs = lin(lo, hi, 700);
      const ab = M.vibronic(xs, s.E00, hwU, fc.from0, s.fw, 'abs'), em = M.vibronic(xs, s.E00, s.hw, fc.to0, s.fw, 'em');
      const mx = Math.max(...fc.from0, ...fc.to0) || 1;
      const sticks = s.stick ? [{ xs: fc.from0.map((_, v) => s.E00 + v * hwU), ys: fc.from0.map((p) => (0.95 * p) / mx), sticks: true, color: c.info, width: 2, alpha: 0.6 }, { xs: fc.to0.map((_, v) => s.E00 - v * s.hw), ys: fc.to0.map((p) => (0.95 * p) / mx), sticks: true, color: c.gold, width: 2, alpha: 0.6 }] : [];
      plot(cv, { x: [lo, hi], y: [0, 1.08], xl: L('波数（cm⁻¹）', 'wavenumber (cm⁻¹)'), yl: L('强度（归一）', 'intensity (norm.)'), series: [...sticks, { xs, ys: ab, color: c.info, width: 2.2, label: L('吸收', 'absorption') }, { xs, ys: em, color: c.gold, width: 2.2, label: L('荧光', 'fluorescence') }], marks: [{ x: s.E00, color: c.muted }] });
      const vmax = fc.from0.indexOf(Math.max(...fc.from0)), mAbs = xs[ab.indexOf(Math.max(...ab))], mEm = xs[em.indexOf(Math.max(...em))];
      return [[L('0–0 带的份额 |⟨0|0⟩|²', 'Share of the 0–0 band |⟨0|0⟩|²'), fix(fc.from0[0], 3), true], [L('吸收最强的是 v′ =', 'Strongest absorption line v′ ='), String(vmax)], [L('两条谱峰之间的距离', 'Distance between the two peaks'), `${fix(mAbs - mEm, 0)} cm⁻¹`], [L('重组能 λ = Sħω（每一边）', 'Reorganisation energy λ = Sħω (each side)'), `${fix(s.S * s.hw, 0)} cm⁻¹`], [L('FC 因子之和（应为 1）', 'Sum of FC factors (should be 1)'), fix(fc.from0.reduce((a, b) => a + b, 0), 4)]];
    },
  };

  // ── 4. Franck–Condon 的波函数 ─────────────────────────────────────
  DEMOS.fcwave = {
    title: L('竖直跃迁：两条势能曲线、振动波函数和它们的重叠', 'Vertical transitions: two potential curves, vibrational wavefunctions and their overlap'), kind: 'exact',
    intro: L('下面是基态的势能曲线和它的 v = 0 波函数，上面是激发态的曲线，平衡位置错开了 d。从 v = 0 往上竖直画一条线，落在上面的曲线哪里，那附近的振动能级就最可能被激发。选一个上面的振动能级 v′，下图画出两个波函数的乘积：它的积分就是重叠，平方就是那条振动带的强度。', 'Below is the ground-state curve with its v = 0 wavefunction; above is the excited-state curve, its minimum shifted by d. Draw a vertical line up from v = 0: where it hits the upper curve, the nearby vibrational levels are the most likely to be excited. Pick an upper level v′; the lower panel shows the product of the two wavefunctions: its integral is the overlap, and its square the strength of that vibronic band.'),
    ctl: [['d', L('平衡位置的错开 d（无量纲）', 'Shift of the minimum d (dimensionless)'), 0, 3.5, 0.01, 1.6, (v) => `${v.toFixed(2)} · S = ${(v * v / 2).toFixed(2)}`], ['r', L('上下频率比 ω′/ω″', 'Frequency ratio ω′/ω″'), 0.5, 1.6, 0.01, 1, (v) => v.toFixed(2)], ['v', L('上面的振动能级 v′', 'Upper vibrational level v′'), 0, 10, 1, 1, (v) => String(v)]],
    btn: [[L('不错开（只有 0–0）', 'No shift (only 0–0)'), { d: 0, r: 1, v: 0 }], [L('错开一点', 'Small shift'), { d: 1.2, r: 1, v: 1 }], [L('错开很多', 'Large shift'), { d: 3, r: 1, v: 4 }]],
    figs: [[0.7, L('势能曲线（ħω″ 为单位）和振动波函数，蓝线是 v = 0 出发的竖直跃迁。', 'Potential curves (in units of ħω″) and vibrational wavefunctions; the blue line is the vertical transition from v = 0.')], [0.36, L('ψ₀″(x) ψ_v′(x)：面积就是重叠积分。', 'ψ₀″(x) ψ_v′(x): its area is the overlap integral.')]],
    note: L('单位 ħ = m = ω″ = 1。下面的势 V″ = x²/2，上面的 V′ = ΔE + (ω′/ω″)² (x − d)²/2，这里为了画图取 ΔE = 6。波函数用 Hermite 函数的三项递推，重叠在细格子上积分。', 'Units ħ = m = ω″ = 1. The lower curve V″ = x²/2, the upper V′ = ΔE + (ω′/ω″)² (x − d)²/2 with ΔE = 6 for drawing. Wavefunctions use the three-term Hermite recursion; overlaps are integrated on a fine grid.'),
    draw(s, [cv, cv2], c) {
      const r = s.r, d = s.d, dE = 6, x0 = -4.2, x1 = Math.max(4.5, d + 4), xs = lin(x0, x1, 500), sc = 0.9;
      const fc = M.fcFactors(1, r, d, 12, 1600), lo = xs.map((x) => x * x / 2), up = xs.map((x) => dE + (r * r * (x - d) ** 2) / 2);
      const series = [{ xs, ys: lo, color: c.ink2, width: 1.6 }, { xs, ys: up, color: c.ink2, width: 1.6 }];
      const psi0 = xs.map((x) => M.hoPsi(0, x, 1)[0]);
      series.push({ xs, ys: psi0.map((p) => 0.5 + sc * p), color: c.info, width: 2 });
      for (let v = 0; v <= 10; v++) {
        const E = dE + r * (v + 0.5), ps = xs.map((x) => M.hoPsi(v, x - d, r)[v]);
        series.push({ xs, ys: ps.map((p) => E + (v === s.v ? 1.3 * sc : 0.5 * sc) * p), color: v === s.v ? c.gold : c.line, width: v === s.v ? 2.2 : 1 });
      }
      plot(cv, { x: [x0, x1], y: [0, dE + r * 11.5 + 1], xl: L('核坐标 x', 'nuclear coordinate x'), yl: L('能量 / ħω″', 'energy / ħω″'), series, arrows: [{ from: [0, 0.5], to: [0, dE + (r * r * d * d) / 2], color: c.info, width: 2 }] });
      const prod = xs.map((x) => M.hoPsi(0, x, 1)[0] * M.hoPsi(s.v, x - d, r)[s.v]);
      const ov = M.trapz(xs, prod), mx = Math.max(0.05, ...prod.map(Math.abs));
      plot(cv2, { x: [x0, x1], y: [-mx * 1.1, mx * 1.1], xl: 'x', yl: 'ψ₀″ψ_v′', series: [{ xs, ys: prod, color: c.gold, width: 2, fill: true }] });
      return [[L('重叠 ⟨0″|v′⟩', 'Overlap ⟨0″|v′⟩'), fix(ov, 4)], [L('Franck–Condon 因子 |⟨0″|v′⟩|²', 'Franck–Condon factor |⟨0″|v′⟩|²'), fix(ov * ov, 4), true], [L('最强的一条 v′', 'Strongest line v′'), String(fc.from0.indexOf(Math.max(...fc.from0)))], [L('竖直跃迁落点 V′(0) − V′_min', 'Vertical landing point V′(0) − V′_min'), `${fix((r * r * d * d) / 2, 2)} ħω″`]];
    },
  };

  // ── 5. 能隙律与 Kasha 规则 ────────────────────────────────────────
  DEMOS.gap = {
    title: L('能隙律：能隙越大，无辐射跃迁越慢；Kasha 规则和薁的例外', 'The energy-gap law: the bigger the gap, the slower the radiationless jump; Kasha’s rule and the azulene exception'), kind: 'toy',
    intro: L('无辐射跃迁要把一大份电子能量一次塞进很多个振动量子里。能隙 ΔE 是 ħω 的 p 倍，就要同时激发大约 p 个量子，概率像 Sᵖ/p! 一样随 p 急剧变小：能隙每多一个振动量子，速率降一个数量级左右。S₂ 和 S₁ 通常挨得很近，S₂ → S₁ 的内转换只要几十飞秒，比任何发光都快，所以发光几乎总是从最低的激发态出来（Kasha 规则）。薁的 S₂ 和 S₁ 隔得远，S₁ 却离基态近：它反过来从 S₂ 发荧光。', 'A radiationless jump has to dump a big chunk of electronic energy into many vibrational quanta at once. A gap ΔE equal to p times ħω means exciting roughly p quanta simultaneously, and the probability falls like Sᵖ/p!: every extra quantum of gap costs about an order of magnitude in rate. S₂ and S₁ are usually close, so S₂ → S₁ internal conversion takes tens of femtoseconds, faster than any emission, and light comes almost always from the lowest excited state (Kasha’s rule). In azulene S₂ sits far above S₁, while S₁ is close to the ground state: it fluoresces from S₂ instead.'),
    ctl: [['E1', L('S₁ 能量（cm⁻¹）', 'S₁ energy (cm⁻¹)'), 5000, 40000, 100, 31000, (v) => `${v.toFixed(0)} cm⁻¹`], ['E2', L('S₂ 能量（cm⁻¹）', 'S₂ energy (cm⁻¹)'), 6000, 50000, 100, 35000, (v) => `${v.toFixed(0)} cm⁻¹`], ['hw', L('接受模 ħω_M（cm⁻¹）', 'Accepting mode ħω_M (cm⁻¹)'), 800, 3300, 10, 1500, (v) => `${v.toFixed(0)} cm⁻¹`], ['S', L('Huang–Rhys 因子 S', 'Huang–Rhys factor S'), 0.2, 3, 0.01, 1, (v) => v.toFixed(2)], ['kr', L('S₁、S₂ 的辐射速率 log₁₀ k_r（s⁻¹）', 'S₁, S₂ radiative rate log₁₀ k_r (s⁻¹)'), 5, 9.5, 0.01, 7.5, (v) => sci(e10(v))]],
    btn: [[L('一般的芳烃', 'Ordinary aromatic'), { E1: 31000, E2: 35000, hw: 1500, S: 1 }], [L('像薁', 'Azulene-like'), { E1: 14300, E2: 28300, hw: 1500, S: 1 }], [L('C–H 振动当接受模', 'C–H stretch as acceptor'), { E1: 15000, E2: 30000, hw: 3000, S: 0.6 }], [L('换成 C–D', 'Deuterated (C–D)'), { E1: 15000, E2: 30000, hw: 2200, S: 0.6 }]],
    figs: [[0.55, L('无辐射速率随能隙变化（对数坐标）。实线是单模多声子公式，虚线是 Englman–Jortner 的渐近式；两条竖线是 S₂ − S₁ 和 S₁ − S₀。', 'Radiationless rate against gap (log scale). Solid: the single-mode multiphonon formula; dashed: the Englman–Jortner asymptotic law. The two vertical lines mark S₂ − S₁ and S₁ − S₀.')]],
    note: L('玩具模型：一个接受模、T = 0，k = C e^{−S} Sᵖ/Γ(p + 1)，p = ΔE/ħω_M，前因子 C = 10¹³ s⁻¹（电子耦合的量级）。Englman–Jortner 弱耦合式 k ≈ C e^{−S} e^{−γΔE/ħω}/√(2πp)，γ = ln(ΔE/Sħω) − 1，就是上式的 Stirling 展开。真实分子的前因子差好几个数量级，C–H / C–D 的同位素效应正是能隙律的经典证据之一；薁的 S₂ 荧光量子产率只有百分之几，但比 S₁ 的高得多。', 'Toy model: one accepting mode, T = 0, k = C e^{−S} Sᵖ/Γ(p + 1), p = ΔE/ħω_M, prefactor C = 10¹³ s⁻¹ (the order of the electronic coupling). The Englman–Jortner weak-coupling law k ≈ C e^{−S} e^{−γΔE/ħω}/√(2πp), γ = ln(ΔE/Sħω) − 1, is the Stirling expansion of the same formula. Real prefactors vary by orders of magnitude; the C–H / C–D isotope effect is one of the classic pieces of evidence for the gap law. Azulene’s S₂ fluorescence yield is only a few percent, but far above its S₁ yield.'),
    draw(s, [cv], c) {
      const E2 = Math.max(s.E2, s.E1 + 200), kr = e10(s.kr), R = M.kasha({ E1: s.E1, E2, kr1: kr, kr2: kr, hw: s.hw, S: s.S });
      const xs = lin(s.hw * 0.5, 40000, 400);
      plot(cv, { logy: true, x: [0, 40000], y: [-2, 14], xl: L('能隙 ΔE（cm⁻¹）', 'gap ΔE (cm⁻¹)'), yl: 'k_nr (s⁻¹)', series: [{ xs, ys: xs.map((x) => M.gapRate(x, s.hw, s.S)), color: c.accent, width: 2.4, label: L('单模公式', 'single mode') }, { xs: xs.filter((x) => x > 2 * s.hw), ys: xs.filter((x) => x > 2 * s.hw).map((x) => M.gapEJ(x, s.hw, s.S)), color: c.gold, dash: [5, 4], label: 'Englman–Jortner' }], hmarks: [{ y: kr, color: c.ok }], marks: [{ x: E2 - s.E1, y: R.k21, color: c.danger }, { x: s.E1, y: R.k10, color: c.info }], texts: [{ s: 'k_r', x: 38000, y: kr * 3, color: c.ok, align: 'right' }] });
      const kashaOK = R.phiS2 < 0.01;
      return [[L('S₂ → S₁ 内转换', 'S₂ → S₁ internal conversion'), `${sci(R.k21)} s⁻¹`], [L('S₂ 的寿命', 'S₂ lifetime'), time(R.tauS2)], [L('S₂ 发荧光的量子产率', 'S₂ fluorescence yield'), fmt(R.phiS2, 3), true], [L('S₁ 发荧光的量子产率', 'S₁ fluorescence yield'), fmt(R.phiS1, 3)], [L('Kasha 规则', 'Kasha’s rule'), kashaOK ? `<span class="pc-ok">${L('成立：光从 S₁ 出来', 'holds: light comes from S₁')}</span>` : `<span class="pc-no">${L('不成立：S₂ 也发光', 'broken: S₂ emits too')}</span>`]];
    },
  };

  // ── 6. Förster 和 Dexter ──────────────────────────────────────────
  DEMOS.fret = {
    title: L('Förster 共振能量转移：分子尺子上的 1/r⁶，和 Dexter 的指数', 'Förster resonance energy transfer: the 1/r⁶ of the molecular ruler, and Dexter’s exponential'), kind: 'approx',
    intro: L('激发的给体 D 不必发出光子，也能通过偶极–偶极相互作用把能量交给附近的受体 A。效率 E = 1/(1 + (r/R₀)⁶) 在 Förster 半径 R₀ 处正好一半，几纳米之内从接近 1 掉到接近 0，所以能当尺子量蛋白质和 DNA 里的距离。R₀ 由给体的发射和受体的吸收重叠多少（重叠积分 J）、两个偶极的取向 κ² 和给体的荧光量子产率决定。Dexter 转移靠电子云直接交换，只在接触距离起作用，随距离指数衰减；三重态的能量转移靠它。', 'An excited donor D can hand its energy to a nearby acceptor A through dipole–dipole coupling without emitting a photon. The efficiency E = 1/(1 + (r/R₀)⁶) is exactly one half at the Förster radius R₀ and drops from near 1 to near 0 within a few nanometres, which makes it a ruler for distances in proteins and DNA. R₀ is set by how much the donor’s emission overlaps the acceptor’s absorption (the overlap integral J), the dipole orientation factor κ² and the donor’s fluorescence yield. Dexter transfer works by direct electron exchange, only at contact, and decays exponentially with distance; triplet energy transfer relies on it.'),
    ctl: [['r', L('给体–受体距离 r（nm）', 'Donor–acceptor distance r (nm)'), 0.5, 15, 0.05, 5, (v) => `${v.toFixed(2)} nm`], ['lD', L('给体发射峰（nm）', 'Donor emission peak (nm)'), 350, 700, 1, 565, (v) => `${v.toFixed(0)} nm`], ['lA', L('受体吸收峰（nm）', 'Acceptor absorption peak (nm)'), 350, 750, 1, 649, (v) => `${v.toFixed(0)} nm`], ['le', L('受体 log₁₀ ε_max（M⁻¹ cm⁻¹）', 'Acceptor log₁₀ ε_max (M⁻¹ cm⁻¹)'), 3, 5.5, 0.01, Math.log10(2.5e5), (v) => fmt(e10(v), 3)], ['phi', L('给体荧光量子产率 Φ_D', 'Donor fluorescence yield Φ_D'), 0.01, 1, 0.01, 0.3, (v) => v.toFixed(2)], ['k2', L('取向因子 κ²', 'Orientation factor κ²'), 0, 4, 0.01, 2 / 3, (v) => v.toFixed(2)], ['n', L('介质折射率 n', 'Refractive index n'), 1.3, 1.6, 0.01, 1.4, (v) => v.toFixed(2)]],
    btn: [[L('像 Cy3 → Cy5', 'Cy3 → Cy5-like'), { lD: 565, lA: 649, le: Math.log10(2.5e5), phi: 0.3, k2: 2 / 3, n: 1.4 }], [L('重叠很少', 'Little overlap'), { lD: 450, lA: 650 }], [L('偶极互相垂直（κ² = 0）', 'Perpendicular dipoles (κ² = 0)'), { k2: 0 }], [L('共线排列（κ² = 4）', 'Collinear dipoles (κ² = 4)'), { k2: 4 }]],
    figs: [[0.45, L('给体的发射（金）和受体的吸收（蓝），阴影是乘积 F_D ε_A λ⁴，重叠积分 J 就是它的面积。', 'Donor emission (gold) and acceptor absorption (blue); the shading is the product F_D ε_A λ⁴, whose area is the overlap integral J.')], [0.45, L('转移效率随距离：Förster（实线）和 Dexter（虚线，接触距离 0.5 nm、衰减长度 0.1 nm）。', 'Transfer efficiency against distance: Förster (solid) and Dexter (dashed, contact at 0.5 nm, decay length 0.1 nm).')]],
    note: L('R₀⁶ = 9 ln10 κ² Φ_D J / (128 π⁵ n⁴ N_A)，J = ∫F_D(λ) ε_A(λ) λ⁴ dλ / ∫F_D dλ。两条谱都用高斯（半高宽 40 nm）代替真实谱形，所以 R₀ 只是量级（真实的 Cy3–Cy5 对 R₀ 约 5–6 nm）。κ² = 2/3 是两个偶极快速、各向同性转动时的平均值；固定取向时 κ² 在 0 到 4 之间，这是 FRET 测距最大的不确定来源之一。点偶极近似在 r 小于分子大小时失效。Dexter 曲线是示意：k_ET τ_D 在接触距离取 10⁴。', 'R₀⁶ = 9 ln10 κ² Φ_D J / (128 π⁵ n⁴ N_A), J = ∫F_D(λ) ε_A(λ) λ⁴ dλ / ∫F_D dλ. Both spectra are Gaussians (40 nm FWHM) standing in for real band shapes, so R₀ is only an order of magnitude (the real Cy3–Cy5 pair has R₀ of about 5–6 nm). κ² = 2/3 is the average for fast isotropic tumbling of both dipoles; for fixed orientations κ² ranges from 0 to 4, one of the largest uncertainties in FRET distances. The point-dipole approximation fails when r is smaller than the molecules. The Dexter curve is illustrative: k_ET τ_D is 10⁴ at contact.'),
    draw(s, [cv, cv2], c) {
      const eps = e10(s.le), J = M.overlapJ(s.lD, 40, s.lA, 40, eps), R0 = M.forsterR0(s.k2, s.phi, s.n, J), E = M.fretE(s.r, R0);
      const xs = lin(300, 800, 500), F = xs.map((l) => M.gauss(l, s.lD, 40)), A = xs.map((l) => M.gauss(l, s.lA, 40));
      const P = xs.map((l, i) => F[i] * A[i] * (l / s.lA) ** 4);
      plot(cv, { x: [300, 800], y: [0, 1.1], xl: L('波长（nm）', 'wavelength (nm)'), yt: [], series: [{ xs, ys: P, color: c.ok, width: 1, fill: true, alpha: 0.5 }, { xs, ys: F, color: c.gold, width: 2.2, label: L('给体发射', 'donor emission') }, { xs, ys: A, color: c.info, width: 2.2, label: L('受体吸收', 'acceptor absorption') }] });
      const rs = lin(0.3, 15, 400);
      plot(cv2, { x: [0, 15], y: [0, 1.05], xl: 'r (nm)', yl: L('转移效率 E', 'efficiency E'), series: [{ xs: rs, ys: rs.map((r) => M.fretE(r, R0)), color: c.accent, width: 2.4, label: 'Förster' }, { xs: rs, ys: rs.map((r) => (r < 0.5 ? 1 : M.dexterE(r, 0.5, 0.1, 1e4))), color: c.danger, dash: [5, 4], label: 'Dexter' }], marks: [{ x: s.r, y: E, color: c.gold }, { x: R0, y: 0.5, color: c.muted }], hmarks: [{ y: 0.5, color: c.line }] });
      return [[L('重叠积分 J', 'Overlap integral J'), `${sci(J)} M⁻¹ cm⁻¹ nm⁴`], [L('Förster 半径 R₀', 'Förster radius R₀'), `${fix(R0, 2)} nm`, true], [L('这个距离上的效率 E', 'Efficiency E at this distance'), pc(E, 1), true], [L('k_ET / k_D = (R₀/r)⁶', 'k_ET / k_D = (R₀/r)⁶'), fmt((R0 / s.r) ** 6, 3)], [L('E 从 90 % 降到 10 % 的距离', 'Distance over which E falls from 90 % to 10 %'), `${fix(R0 * (9 ** (1 / 6) - (1 / 9) ** (1 / 6)), 2)} nm`]];
    },
  };

  // ── 7. Kasha 激子：H 聚集和 J 聚集 ────────────────────────────────
  DEMOS.aggregate = {
    title: L('分子排成一行：H 聚集蓝移、J 聚集红移，亮度集中到一个态', 'Molecules in a row: H aggregates shift blue, J aggregates red, and the brightness gathers into one state'), kind: 'exact',
    intro: L('N 个相同的分子挨得很近，一个分子的激发会通过跃迁偶极之间的耦合 V 跳到邻居上，激发不再属于某一个分子，而是整排共有的“Frenkel 激子”。偶极肩并肩（和连线垂直）时 V > 0，所有偶极同相的那个态在最上面，只有它能吸收光：吸收蓝移，荧光被压住（H 聚集）。偶极头尾相接、和连线夹角小于 54.7° 时 V < 0，亮态在最下面：吸收红移、变窄、荧光变快（J 聚集，超辐射）。正好 54.7° 时耦合为零。', 'Place N identical molecules close together and an excitation hops between neighbours through the coupling V of their transition dipoles; it no longer belongs to one molecule but to the whole row, a “Frenkel exciton”. With dipoles side by side (perpendicular to the line) V > 0, and the state with all dipoles in phase lies at the top and is the only one that absorbs: absorption shifts blue and emission is suppressed (an H aggregate). With dipoles head-to-tail, at less than 54.7° to the line, V < 0 and the bright state is at the bottom: absorption shifts red, narrows and emission speeds up (a J aggregate, superradiance). At exactly 54.7° the coupling vanishes.'),
    ctl: [['N', L('分子数 N', 'Number of molecules N'), 1, 30, 1, 12, (v) => String(v)], ['th', L('偶极和连线的夹角 θ', 'Angle θ between dipole and row'), 0, 90, 0.5, 90, (v) => `${v.toFixed(1)}°`], ['mu', L('跃迁偶极 μ（D）', 'Transition dipole μ (D)'), 1, 15, 0.1, 8, (v) => `${v.toFixed(1)} D`], ['r', L('分子间距 r（nm）', 'Spacing r (nm)'), 0.35, 2, 0.01, 0.7, (v) => `${v.toFixed(2)} nm`], ['g', L('谱线展宽（cm⁻¹）', 'Line broadening (cm⁻¹)'), 50, 1500, 10, 250, (v) => `${v.toFixed(0)} cm⁻¹`]],
    chk: [['all', L('所有分子对都耦合（1/r³），不只最近邻', 'Couple every pair (1/r³), not only neighbours'), true]],
    btn: [[L('H 聚集（θ = 90°）', 'H aggregate (θ = 90°)'), { th: 90 }], [L('J 聚集（θ = 20°）', 'J aggregate (θ = 20°)'), { th: 20 }], [L('魔角 54.7°', 'Magic angle 54.7°'), { th: 54.74 }], [L('二聚体', 'Dimer'), { N: 2 }]],
    figs: [[0.5, L('激子态（竖线高度是振子强度，以单个分子为 1）和展宽后的吸收谱；灰色虚线是单个分子。', 'Exciton states (stick height is oscillator strength, one molecule = 1) and the broadened absorption; the grey dashed curve is a single molecule.')], [0.32, L('最近邻耦合随夹角 θ 的变化：54.7° 以下是 J，以上是 H。', 'Nearest-neighbour coupling against angle θ: J below 54.7°, H above.')]],
    note: L('点偶极耦合 V = 5.034 μ²(D²)(1 − 3cos²θ)/r³(nm³) cm⁻¹，偶极互相平行。对角化 N × N 的激子哈密顿量（相对单体能量），亮度是 |Σₙ cₙ|²：所有分子的偶极按系数相加。只有最近邻、开端链时亮态能量是 ±2V cos(π/(N+1))，亮度约 0.81N。没有振动耦合（Spano 的理论里它让 H 聚集的谱形变化）、没有无序；真实的 J 聚集（Jelley 和 Scheibe 1936 年发现的假异氰菁）是二维的砖墙结构。', 'Point-dipole coupling V = 5.034 μ²(D²)(1 − 3cos²θ)/r³(nm³) cm⁻¹ with parallel dipoles. The N × N exciton Hamiltonian (relative to the monomer energy) is diagonalised; brightness is |Σₙ cₙ|², the dipoles added with their coefficients. With nearest neighbours only and open ends the bright state sits at ±2V cos(π/(N+1)) with brightness about 0.81N. No vibronic coupling (which in Spano’s theory reshapes H-aggregate spectra) and no disorder; real J aggregates (the pseudoisocyanine found by Jelley and Scheibe in 1936) are two-dimensional brickwork.'),
    draw(s, [cv, cv2], c) {
      const V = M.dipoleCm(s.mu, s.r, (s.th * PI) / 180), N = Math.round(s.N), X = M.exciton(N, V, s.all);
      const span = Math.max(4 * Math.abs(V), 3 * s.g, 400), xs = lin(-span, span, 600);
      const ys = xs.map((e) => X.E.reduce((acc, E, k) => acc + X.f[k] * M.gauss(e, E, s.g), 0)), mono = xs.map((e) => M.gauss(e, 0, s.g));
      const top = Math.max(...X.f, 1) * 1.1;
      plot(cv, { x: [-span, span], y: [0, top], xl: L('能量 − 单体（cm⁻¹）', 'energy − monomer (cm⁻¹)'), yl: L('振子强度', 'oscillator strength'), series: [{ xs, ys: mono, color: c.muted, dash: [4, 4], label: L('单体', 'monomer') }, { xs, ys, color: c.accent, width: 2.2, label: L('聚集体', 'aggregate') }, { xs: X.E, ys: X.f, sticks: true, color: c.gold, width: 2.4 }] });
      const ths = lin(0, 90, 181);
      plot(cv2, { x: [0, 90], y: [-2 * Math.abs(C1(s)) - 1, Math.abs(C1(s)) + 1], xl: 'θ (°)', yl: 'V (cm⁻¹)', series: [{ xs: ths, ys: ths.map((t) => M.dipoleCm(s.mu, s.r, (t * PI) / 180)), color: c.accent, width: 2 }], hmarks: [{ y: 0, color: c.line }], marks: [{ x: s.th, y: V, color: c.gold }, { x: 54.7356, color: c.muted }] });
      const kb = X.f.indexOf(Math.max(...X.f)), kind = Math.abs(V) < 1 ? L('几乎不耦合', 'nearly uncoupled') : V > 0 ? L('H 聚集：蓝移', 'H aggregate: blue shift') : L('J 聚集：红移', 'J aggregate: red shift');
      return [[L('最近邻耦合 V', 'Nearest-neighbour coupling V'), `${fix(V, 0)} cm⁻¹`], [L('类型', 'Type'), kind, true], [L('亮态的位移', 'Shift of the bright state'), `${fix(X.E[kb], 0)} cm⁻¹ · ${fix((X.E[kb] * M.C.cm1) * 1000, 1)} meV`], [L('亮态的振子强度（单体 = 1）', 'Bright-state oscillator strength (monomer = 1)'), fix(X.f[kb], 2)], [L('最低的态亮不亮', 'Is the lowest state bright?'), X.f[0] > 0.5 ? L('亮：荧光快', 'bright: fast emission') : L('暗：荧光被压住', 'dark: emission suppressed')]];
    },
  };
  const C1 = (s) => M.dipoleCm(s.mu, s.r, 0) / 2; // θ = 90° 时的耦合大小，用来定纵轴

  // ── 8. Landau–Zener ──────────────────────────────────────────────
  DEMOS.lz = {
    title: L('Landau–Zener：在能级回避交叉处，跳还是不跳', 'Landau–Zener: at an avoided crossing, jump or stay'), kind: 'exact',
    intro: L('两条透热态的能量随核运动线性交叉，耦合 V 让它们“回避”，绝热能量之间留出 2V 的缝。核走得慢，电子来得及跟着变，体系沿下面的绝热曲线拐过去（绝热）；走得快，电子跟不上，体系留在原来的透热态上，等于跳到了上面的绝热曲线（非绝热）。Landau 和 Zener 1932 年给出跳的概率 P = exp(−2πV²/ħα)，α 是两条透热能量之差的变化速度。这里当场数值求解含时薛定谔方程，和公式对照。', 'Two diabatic energies cross linearly as the nuclei move; a coupling V makes them “avoid” each other, leaving a gap of 2V between the adiabatic energies. If the nuclei move slowly the electron keeps up and the system follows the lower adiabatic curve round the bend (adiabatic); if fast, the electron cannot keep up and the system stays on its diabatic state, which means jumping to the upper adiabatic curve (non-adiabatic). Landau and Zener gave the jump probability in 1932: P = exp(−2πV²/ħα), α being the rate at which the two diabatic energies separate. Here the time-dependent Schrödinger equation is solved numerically on the spot and compared with the formula.'),
    ctl: [['V', L('耦合 V', 'Coupling V'), 0.02, 1, 0.005, 0.3, (v) => v.toFixed(3)], ['a', L('扫过的速度 α（对数）', 'Sweep rate α (log)'), -1.3, 0.8, 0.01, 0, (v) => fmt(e10(v), 3)]],
    btn: [[L('慢：几乎绝热', 'Slow: nearly adiabatic'), { V: 0.4, a: -0.7 }], [L('一半一半', 'Half and half'), { V: 0.3, a: Math.log10((2 * PI * 0.09) / Math.LN2) }], [L('快：几乎全跳', 'Fast: nearly all jump'), { V: 0.08, a: 0.5 }]],
    figs: [[0.42, L('透热能量 ±αt/2（虚线）和绝热能量（实线）。', 'Diabatic energies ±αt/2 (dashed) and adiabatic energies (solid).')], [0.42, L('数值解：在上面绝热态（金）和在透热态 1（蓝）的概率。', 'Numerical solution: probability on the upper adiabatic state (gold) and on diabatic state 1 (blue).')], [0.38, L('跳的概率 P 对 2πV²/α：曲线是 Landau–Zener 公式，点是这一次的数值解。', 'Jump probability P against 2πV²/α: the curve is the Landau–Zener formula, the dot this numerical solution.')]],
    note: L('单位 ħ = 1，H(t) = [[αt/2, V], [V, −αt/2]]。从 t = −T 的下绝热态出发（T 取得足够长，让 αT ≫ V），四阶 Runge–Kutta 积分到 +T，读出上绝热态的布居。透热布居在有限时间里有 ~V/αT 的振荡，绝热布居收敛快得多。公式在 T → ∞、能量严格线性时才精确；真实分子里 α 是核的速度乘以两条势能面斜率之差，交叉附近不只两个态时要用多态版本。', 'Units ħ = 1, H(t) = [[αt/2, V], [V, −αt/2]]. Start on the lower adiabatic state at t = −T (T long enough that αT ≫ V), integrate with fourth-order Runge–Kutta to +T, and read off the upper adiabatic population. The diabatic populations oscillate by ~V/αT at finite times; the adiabatic ones converge much faster. The formula is exact only for T → ∞ and strictly linear energies; in a real molecule α is the nuclear velocity times the difference in slopes of the two surfaces, and with more than two states near the crossing a multistate version is needed.'),
    draw(s, [cv, cv2, cv3], c) {
      const a = e10(s.a), V = s.V, T = Math.max(30 / Math.sqrt(a), (40 * V) / a, 12), dt = Math.min(0.01, 0.15 / (a * T)), R = M.lzSolve(V, a, T, dt, Math.max(1, Math.round(T / dt / 400)));
      const tv = 2.5 * Math.max(V / a * 2, 3 / Math.sqrt(a)), ts = lin(-tv, tv, 300);
      const lo = ts.map((t) => -Math.hypot((a * t) / 2, V)), hi = lo.map((v) => -v), ylim = (a * tv) / 2 * 1.05;
      plot(cv, { x: [-tv, tv], y: [-ylim, ylim], xl: 't', yl: 'E', series: [{ xs: ts, ys: ts.map((t) => (a * t) / 2), color: c.info, dash: [5, 4] }, { xs: ts, ys: ts.map((t) => (-a * t) / 2), color: c.muted, dash: [5, 4] }, { xs: ts, ys: lo, color: c.accent, width: 2.2 }, { xs: ts, ys: hi, color: c.gold, width: 2.2 }] });
      const keep = R.t.map((t, i) => [t, i]).filter(([t]) => Math.abs(t) <= tv * 1.6);
      plot(cv2, { x: [-tv * 1.6, tv * 1.6], y: [0, 1.05], xl: 't', yl: L('概率', 'probability'), series: [{ xs: keep.map((k) => k[0]), ys: keep.map((k) => R.p1[k[1]]), color: c.info, width: 1.8, label: L('透热态 1', 'diabatic 1') }, { xs: keep.map((k) => k[0]), ys: keep.map((k) => R.pUp[k[1]]), color: c.gold, width: 2.2, label: L('上绝热态', 'upper adiabatic') }], hmarks: [{ y: M.lzP(V, a), color: c.danger }] });
      const gs = lin(0, 6, 200), g = (2 * PI * V * V) / a;
      plot(cv3, { x: [0, 6], y: [0, 1.02], xl: '2πV²/ħα', yl: 'P', series: [{ xs: gs, ys: gs.map((x) => Math.exp(-x)), color: c.accent, width: 2.2 }], marks: [{ x: Math.min(g, 6), y: R.final, color: c.danger }] });
      return [[L('Landau–Zener 公式 P', 'Landau–Zener formula P'), fix(M.lzP(V, a), 4)], [L('数值解：跳到上面的概率', 'Numerical: probability of jumping'), fix(R.final, 4), true], [L('Massey 参数 2πV²/ħα', 'Massey parameter 2πV²/ħα'), fix(g, 3)], [L('绝热能隙 2V', 'Adiabatic gap 2V'), fix(2 * V, 3)], [L('积分的模长（应为 1）', 'Norm after integration (should be 1)'), fix(R.norm, 5)]];
    },
  };

  // ── 9. 锥形交叉 ──────────────────────────────────────────────────
  DEMOS.cone = {
    title: L('锥形交叉：两条势能面在一个点上相碰，绕它一圈波函数变号', 'A conical intersection: two surfaces touch at a point, and going round it flips the wavefunction’s sign'), kind: 'toy',
    intro: L('对两个原子的分子，同对称性的两条势能曲线不会交叉（von Neumann–Wigner 不交叉规则）。多原子分子有很多核坐标，两条面可以在一个点上真正相碰，附近的形状像双圆锥：沿“调谐”方向 x 两条透热能量分开，沿“耦合”方向 y 它们之间的耦合打开。激发态的波包滑到锥尖，几十飞秒内就能漏回基态：视觉、DNA 的光稳定性、很多光反应都走这条路。拖动图转一转；把那一圈移到包住锥尖或不包住，看下面绝热态的几何相位是 π 还是 0。', 'In a diatomic molecule two curves of the same symmetry cannot cross (the von Neumann–Wigner non-crossing rule). A polyatomic molecule has many nuclear coordinates, and two surfaces can genuinely touch at a point, shaped nearby like a double cone: along the “tuning” direction x the diabatic energies separate, along the “coupling” direction y the coupling between them opens up. An excited wavepacket slides to the tip and can leak back to the ground state within tens of femtoseconds: vision, the photostability of DNA and many photoreactions go this way. Drag the picture to turn it; move the loop so it encloses the tip or not, and see whether the lower state’s geometric phase is π or 0.'),
    ctl: [['g', L('调谐方向的斜率 g', 'Tuning slope g'), 0.2, 2, 0.01, 1, (v) => v.toFixed(2)], ['h', L('耦合方向的斜率 h', 'Coupling slope h'), 0.1, 2, 0.01, 0.6, (v) => v.toFixed(2)], ['t', L('倾斜 s', 'Tilt s'), -1.5, 1.5, 0.01, 0.4, (v) => v.toFixed(2)], ['x0', L('那一圈的圆心 x₀', 'Loop centre x₀'), -1, 1, 0.01, 0.15, (v) => v.toFixed(2)], ['R', L('那一圈的半径', 'Loop radius'), 0.05, 0.8, 0.01, 0.4, (v) => v.toFixed(2)]],
    btn: [[L('包住锥尖', 'Enclose the tip'), { x0: 0.15, R: 0.4 }], [L('不包住', 'Do not enclose'), { x0: 0.7, R: 0.25 }], [L('倾斜得厉害（“过路”型）', 'Strongly tilted (“sloped”)'), { t: 1.3 }], [L('不倾斜（“尖峰”型）', 'Untilted (“peaked”)'), { t: 0 }]],
    state: () => ({ yaw: 0.7, pitch: 0.55 }),
    figs: [[0.7, L('两个绝热面（金是上面的，蓝是下面的），金色的圈画在下面的面上。按住拖动可以转。', 'The two adiabatic surfaces (gold upper, blue lower); the gold loop is drawn on the lower surface. Drag to rotate.')], [0.3, L('沿着那一圈走一周，下面的绝热能量。', 'The lower adiabatic energy going once round the loop.')]],
    note: L('线性振动耦合模型：H = s x + [[g x, h y], [h y, −g x]]，绝热能量 s x ∓ √(g²x² + h²y²)。几何相位：沿圈逐步对角化，每一步把本征向量的符号选得和上一步连续，走回起点时比较符号；包住锥尖时变号（相位 π，Longuet-Higgins 效应），不包住时不变。真实的锥形交叉不是一个点，而是 N − 2 维的“缝”（N 是内坐标数），这里只画分支平面上的截面。', 'Linear vibronic coupling model: H = s x + [[g x, h y], [h y, −g x]], adiabatic energies s x ∓ √(g²x² + h²y²). Geometric phase: diagonalise step by step round the loop, choosing each eigenvector’s sign continuous with the previous step, and compare signs on returning to the start; enclosing the tip flips the sign (phase π, the Longuet-Higgins effect), otherwise it does not. A real conical intersection is not a point but an (N − 2)-dimensional seam (N internal coordinates); only the cut through the branching plane is drawn here.'),
    draw(s, [cv, cv2], c) {
      if (!cv.dataset.drag) {
        cv.dataset.drag = '1'; cv.classList.add('pc-drag');
        cv.onpointerdown = (e) => { const x0 = e.clientX, y0 = e.clientY, a0 = s.yaw, b0 = s.pitch; try { cv.setPointerCapture(e.pointerId); } catch { /* 旧浏览器 */ } cv.onpointermove = (ev) => { s.yaw = a0 + (ev.clientX - x0) * 0.012; s.pitch = clamp(b0 + (ev.clientY - y0) * 0.012, -0.2, 1.4); s.redraw(); }; cv.onpointerup = cv.onpointercancel = () => { cv.onpointermove = null; }; };
      }
      const { ctx, w, h } = fit(cv), cy = Math.cos(s.yaw), sy = Math.sin(s.yaw), cp = Math.cos(s.pitch), sp = Math.sin(s.pitch), k = Math.min(w, h) * 0.32;
      const P = (x, y, z) => { const x1 = cy * x - sy * y, y1 = sy * x + cy * y; return [w / 2 + x1 * k, h * 0.55 - (z * 0.55 * cp - y1 * sp) * k]; };
      const n = 24, grid = lin(-1, 1, n + 1);
      const surf = (sgn, col) => { ctx.strokeStyle = col; ctx.lineWidth = 1; ctx.globalAlpha = 0.75; for (const fixd of [0, 1]) for (const u of grid) { ctx.beginPath(); grid.forEach((v, j) => { const x = fixd ? u : v, y = fixd ? v : u, E = M.coneE(x, y, s.g, s.h, s.t)[sgn], p = P(x, y, E); if (j) ctx.lineTo(p[0], p[1]); else ctx.moveTo(p[0], p[1]); }); ctx.stroke(); } ctx.globalAlpha = 1; };
      surf(0, c.info); surf(1, c.gold);
      // 坐标轴
      const ax = (x, y, lab) => { const a = P(0, 0, -1.6), b = P(x, y, -1.6); arrow(ctx, a[0], a[1], b[0], b[1], c.muted, 1.4); ctx.fillStyle = c.muted; ctx.font = font(12, 600); ctx.fillText(lab, b[0] + 4, b[1]); };
      ax(1.25, 0, L('x 调谐', 'x tuning')); ax(0, 1.25, L('y 耦合', 'y coupling'));
      const loop = lin(0, 2 * PI, 181).map((a) => [s.x0 + s.R * Math.cos(a), s.R * Math.sin(a)]);
      ctx.strokeStyle = c.danger; ctx.lineWidth = 2.6; ctx.beginPath(); loop.forEach(([x, y], i) => { const p = P(x, y, M.coneE(x, y, s.g, s.h, s.t)[0]); if (i) ctx.lineTo(p[0], p[1]); else ctx.moveTo(p[0], p[1]); }); ctx.stroke();
      const tip = P(0, 0, 0); ctx.fillStyle = c.danger; ctx.beginPath(); ctx.arc(tip[0], tip[1], 4, 0, 2 * PI); ctx.fill();
      const ph = M.berryPhase(s.x0, 0, s.R, s.g, s.h), angs = lin(0, 360, 181), El = loop.map(([x, y]) => M.coneE(x, y, s.g, s.h, s.t)[0]);
      plot(cv2, { x: [0, 360], xl: L('绕圈的角度（°）', 'angle round the loop (°)'), y: [Math.min(...El) - 0.1, Math.max(...El) + 0.1], yl: 'E₋', series: [{ xs: angs, ys: El, color: c.info, width: 2.2 }] });
      const enclosed = Math.abs(s.x0) < s.R;
      const peaked = Math.abs(s.t) < Math.min(s.g, s.h);
      return [[L('圈有没有包住锥尖', 'Does the loop enclose the tip?'), enclosed ? L('包住', 'yes') : L('没有', 'no')], [L('几何相位（数值）', 'Geometric phase (numerical)'), ph ? 'π' : '0', true], [L('圈上最小的能隙', 'Smallest gap on the loop'), fix(Math.min(...loop.map(([x, y]) => 2 * Math.hypot(s.g * x, s.h * y))), 3)], [L('形状', 'Topography'), peaked ? L('尖峰型：下面的面在锥尖是最低点附近', 'peaked: the tip is near a minimum of the lower surface') : L('倾斜型：波包会滑过锥尖', 'sloped: a wavepacket tends to slide past the tip')]];
    },
  };

  // ── 10. Marcus 理论 ──────────────────────────────────────────────
  DEMOS.marcus = {
    title: L('Marcus 理论：两条抛物线，和越放热反而越慢的倒置区', 'Marcus theory: two parabolas, and the inverted region where more downhill means slower'), kind: 'exact',
    intro: L('电子转移前后，分子和周围溶剂的“最舒服的”构型不同。把反应物和产物的自由能画成同一个坐标上的两条抛物线：电子只能在两条曲线相交、能量相同的构型上跳（Franck–Condon 原理的又一次出场）。交点的高度 (ΔG° + λ)²/4λ 就是活化能。放热越多，交点先降低，到 −ΔG° = λ 时降到零，速率最大；再放热，交点又升上去，反应反而变慢：这就是 Marcus 1960 年代预言的倒置区，1984 年 Miller、Calcaterra 和 Closs 第一次清楚地测到它。', 'Before and after electron transfer, the molecule and its surrounding solvent prefer different arrangements. Draw the free energies of reactant and product as two parabolas along one coordinate: the electron can jump only where the curves cross and the energies are equal (the Franck–Condon principle once more). The height of the crossing, (ΔG° + λ)²/4λ, is the activation energy. As the reaction gets more downhill the crossing first drops, reaching zero at −ΔG° = λ where the rate peaks; further downhill it rises again and the reaction slows: the inverted region Marcus predicted, first seen clearly by Miller, Calcaterra and Closs in 1984.'),
    ctl: [['lam', L('重组能 λ（eV）', 'Reorganisation energy λ (eV)'), 0.1, 2.5, 0.01, 1, (v) => `${v.toFixed(2)} eV`], ['dG', L('反应自由能 ΔG°（eV）', 'Reaction free energy ΔG° (eV)'), -3, 0.6, 0.01, -0.5, (v) => `${v.toFixed(2)} eV`], ['V', L('电子耦合 V（meV）', 'Electronic coupling V (meV)'), 0.1, 50, 0.1, 5, (v) => `${v.toFixed(1)} meV`], ['T', L('温度 T（K）', 'Temperature T (K)'), 77, 400, 1, 298, (v) => `${v.toFixed(0)} K`], ['hw', L('高频模 ħω（eV）', 'High-frequency mode ħω (eV)'), 0.08, 0.3, 0.005, 0.18, (v) => `${v.toFixed(3)} eV · ${(v / M.C.cm1).toFixed(0)} cm⁻¹`], ['S', L('高频模的 S', 'S of the high-frequency mode'), 0, 3, 0.01, 1, (v) => v.toFixed(2)]],
    chk: [['mlj', L('高频振动按量子处理（Marcus–Levich–Jortner）', 'Treat the high-frequency mode quantum mechanically (Marcus–Levich–Jortner)'), true]],
    btn: [[L('正常区', 'Normal region'), { dG: -0.4 }], [L('无活化（−ΔG° = λ）', 'Activationless (−ΔG° = λ)'), { dG: -1, lam: 1 }], [L('倒置区', 'Inverted region'), { dG: -2.2, lam: 1 }], [L('低温', 'Low temperature'), { T: 77 }]],
    figs: [[0.55, L('反应物（蓝）和产物（金）的自由能曲线；红点是交点，箭头是活化能。', 'Free-energy curves of reactant (blue) and product (gold); the red dot is the crossing, the arrow the activation energy.')], [0.5, L('速率常数随驱动力 −ΔG°（对数坐标）：经典 Marcus（虚线）是对称的抛物线，量子化的高频模让倒置区一侧衰减得慢得多。', 'Rate constant against driving force −ΔG° (log scale): classical Marcus (dashed) is a symmetric parabola; quantising the high-frequency mode makes the inverted side fall off far more slowly.')]],
    note: L('k = (2π/ħ) V² (4πλk_BT)^{−1/2} exp(−(ΔG° + λ)²/4λk_BT)（非绝热，V 小）。MLJ：k = (2π/ħ) V² (4πλ_s k_BT)^{−1/2} Σᵥ e^{−S}Sᵛ/v! exp(−(ΔG° + λ_s + vħω)²/4λ_s k_BT)，这里 λ_s 取滑杆上的 λ，高频模另外贡献 Sħω 的重组能。V 大到和 k_BT 相当时进入绝热电子转移，公式失效；溶剂动力学慢时速率还会被溶剂弛豫限制。', 'k = (2π/ħ) V² (4πλk_BT)^{−1/2} exp(−(ΔG° + λ)²/4λk_BT) (non-adiabatic, small V). MLJ: k = (2π/ħ) V² (4πλ_s k_BT)^{−1/2} Σᵥ e^{−S}Sᵛ/v! exp(−(ΔG° + λ_s + vħω)²/4λ_s k_BT), with λ_s the slider’s λ and the high-frequency mode adding a further Sħω of reorganisation energy. Once V approaches k_BT the transfer becomes adiabatic and the formula fails; with slow solvent dynamics the rate can also be limited by solvent relaxation.'),
    draw(s, [cv, cv2], c) {
      const lam = s.lam, dG = s.dG, qs = lin(-0.8, 1.8, 300), q = M.marcusCross(lam, dG), Gb = M.marcusBarrier(dG, lam);
      const GR = qs.map((x) => M.marcusCurves(x, lam, dG)[0]), GP = qs.map((x) => M.marcusCurves(x, lam, dG)[1]);
      const yl = [Math.min(dG, 0) - 0.3, Math.max(2 * lam, Gb + 0.4, 0.8)];
      plot(cv, { x: [-0.8, 1.8], y: yl, xl: L('反应坐标 q', 'reaction coordinate q'), yl: 'G (eV)', series: [{ xs: qs, ys: GR, color: c.info, width: 2.4, label: L('反应物', 'reactant') }, { xs: qs, ys: GP, color: c.gold, width: 2.4, label: L('产物', 'product') }], marks: [{ x: q, y: lam * q * q, color: c.danger }], arrows: Gb > 0.02 ? [{ from: [0, 0], to: [0, Gb], color: c.danger, width: 2 }] : [], hmarks: [{ y: 0, color: c.line }, { y: dG, color: c.line }] });
      const V = s.V / 1000, xs = lin(-0.6, 3, 300);
      const kc = xs.map((x) => M.marcusK(-x, lam, V, s.T)), km = xs.map((x) => M.mljK(-x, lam, V, s.hw, s.S, s.T));
      const cur = s.mlj ? M.mljK(dG, lam, V, s.hw, s.S, s.T) : M.marcusK(dG, lam, V, s.T);
      plot(cv2, { logy: true, x: [-0.6, 3], y: [0, 14], xl: '−ΔG° (eV)', yl: 'k (s⁻¹)', series: [{ xs, ys: kc, color: c.muted, dash: [5, 4], label: L('经典 Marcus', 'classical Marcus') }, ...(s.mlj ? [{ xs, ys: km, color: c.accent, width: 2.4, label: 'MLJ' }] : [])], marks: [{ x: -dG, y: cur, color: c.danger }, { x: lam, color: c.line }] });
      const region = Math.abs(-dG - lam) < 0.05 ? L('无活化区', 'activationless') : -dG < lam ? L('正常区', 'normal region') : L('倒置区', 'inverted region');
      return [[L('活化能 ΔG‡ = (ΔG° + λ)²/4λ', 'Activation energy ΔG‡ = (ΔG° + λ)²/4λ'), `${fix(Gb, 3)} eV · ${fix(Gb / (M.C.kB * s.T), 1)} k_BT`], [L('交点的位置 q*', 'Crossing point q*'), fix(q, 3)], [L('所在区域', 'Region'), region, true], [L('速率常数 k', 'Rate constant k'), `${sci(cur)} s⁻¹`, true], [L('最大速率出现在 −ΔG° =', 'Maximum classical rate at −ΔG° ='), `${fix(lam, 2)} eV`]];
    },
  };

  // ── 11. TADF ─────────────────────────────────────────────────────
  DEMOS.tadf = {
    title: L('热活化延迟荧光：让三重态借热量回到单重态，OLED 的效率从 25 % 到接近 100 %', 'Thermally activated delayed fluorescence: letting triplets borrow heat to get back to the singlet, taking OLED efficiency from 25 % to nearly 100 %'), kind: 'exact',
    intro: L('OLED 里电子和空穴相遇，按自旋统计 1/4 成为单重态、3/4 成为三重态。普通荧光分子的三重态不发光，内量子效率上限只有 25 %。如果 S₁ 和 T₁ 之间的能隙 ΔE_ST 只有零点几 eV，室温的热量就能把三重态推回单重态（反向系间窜越 RISC），再发出荧光：先是几纳秒的“瞬时荧光”，后面跟着微秒级的“延迟荧光”。把 ΔE_ST 调小、把温度调高，看延迟成分和电致发光效率怎么变。', 'In an OLED electrons and holes meet and, by spin statistics, form singlets a quarter of the time and triplets three quarters of the time. In ordinary fluorescent emitters the triplets are dark, capping the internal efficiency at 25 %. If the gap ΔE_ST between S₁ and T₁ is only a few tenths of an eV, room-temperature heat can push triplets back up to the singlet (reverse intersystem crossing, RISC), which then fluoresces: nanosecond “prompt” fluorescence followed by microsecond “delayed” fluorescence. Shrink ΔE_ST and raise the temperature to see the delayed component and the electroluminescence efficiency change.'),
    ctl: [['dE', L('单重–三重能隙 ΔE_ST（eV）', 'Singlet–triplet gap ΔE_ST (eV)'), 0, 0.5, 0.001, 0.083, (v) => `${(v * 1000).toFixed(0)} meV`], ['T', L('温度 T（K）', 'Temperature T (K)'), 20, 400, 1, 300, (v) => `${v.toFixed(0)} K`], ['kr', 'log₁₀ k_r (s⁻¹)', 5, 9, 0.01, 7.2, (v) => sci(e10(v))], ['kisc', 'log₁₀ k_ISC (s⁻¹)', 5, 10, 0.01, 7.7, (v) => sci(e10(v))], ['knrS', L('S₁ 的无辐射 log₁₀ k（s⁻¹）', 'S₁ radiationless log₁₀ k (s⁻¹)'), 3, 9, 0.01, 5.5, (v) => sci(e10(v))], ['knrT', L('T₁ 的无辐射 log₁₀ k（s⁻¹）', 'T₁ radiationless log₁₀ k (s⁻¹)'), 1, 7, 0.01, 3.5, (v) => sci(e10(v))]],
    btn: [[L('像 4CzIPN（ΔE_ST ≈ 0.08 eV）', '4CzIPN-like (ΔE_ST ≈ 0.08 eV)'), { dE: 0.083, T: 300, kr: 7.2, kisc: 7.7, knrS: 5.5, knrT: 3.5 }], [L('普通荧光分子（ΔE_ST = 0.5 eV）', 'Ordinary fluorophore (ΔE_ST = 0.5 eV)'), { dE: 0.5, T: 300 }], [L('同一个 TADF 分子在 77 K', 'The same TADF emitter at 77 K'), { dE: 0.083, T: 77 }], [L('能隙为零（理想）', 'Zero gap (ideal)'), { dE: 0 }]],
    figs: [[0.5, L('脉冲激发后荧光强度随时间（对数坐标）：先是瞬时荧光的快衰减，再是延迟荧光的慢尾巴。', 'Fluorescence intensity after a pulse (log scale): the fast decay of prompt fluorescence, then the slow tail of delayed fluorescence.')], [0.45, L('瞬时（蓝）和延迟（金）荧光量子产率随温度：延迟部分像 Arrhenius 一样被热激活。', 'Prompt (blue) and delayed (gold) fluorescence yields against temperature: the delayed part is thermally activated, like Arrhenius.')]],
    note: L('两态一阶动力学：dS/dt = −(k_r + k_nr,S + k_ISC) S + k_RISC T，dT/dt = k_ISC S − (k_RISC + k_nr,T) T，解析求解（两个指数）。k_RISC 取细致平衡 (k_ISC/3) e^{−ΔE_ST/k_BT}，因子 1/3 是三重态的三个子能级。真实的 RISC 还要靠自旋–振动耦合（经过高一点的三重态 T₂ 和局域激发态），所以不简单地服从这个式子。电致发光的内效率 = ¼ Φ_F(从 S₁ 出发) + ¾ Φ_F(从 T₁ 出发)；外量子效率还要乘出光效率（约 20–30 %）和载流子平衡。预设的速率是量级，不是 4CzIPN 的测量值。', 'Two-state first-order kinetics: dS/dt = −(k_r + k_nr,S + k_ISC) S + k_RISC T, dT/dt = k_ISC S − (k_RISC + k_nr,T) T, solved analytically (two exponentials). k_RISC follows detailed balance, (k_ISC/3) e^{−ΔE_ST/k_BT}, the 1/3 being the three triplet sublevels. Real RISC also relies on spin–vibronic coupling (through a slightly higher triplet T₂ and locally excited states), so it does not simply obey this formula. The internal electroluminescence efficiency is ¼ Φ_F(starting in S₁) + ¾ Φ_F(starting in T₁); the external quantum efficiency also multiplies by the outcoupling (about 20–30 %) and the charge balance. The preset rates are orders of magnitude, not measured values for 4CzIPN.'),
    draw(s, [cv, cv2], c) {
      const p = { kr: e10(s.kr), knrS: e10(s.knrS), kISC: e10(s.kisc), knrT: e10(s.knrT), dEST: s.dE, T: s.T }, R = M.tadf(p);
      const t0 = Math.log10(R.tauPF) - 1.5, t1 = Math.max(Math.log10(R.tauDF) + 1, t0 + 3), ts = lin(t0, t1, 500).map(e10);
      plot(cv, { logx: true, logy: true, x: [t0, t1], y: [-7, 0.2], xl: L('时间（s）', 'time (s)'), yl: L('荧光强度（相对）', 'fluorescence (rel.)'), series: [{ xs: ts, ys: ts.map((t) => Math.max(R.fromS(t), 1e-9)), color: c.accent, width: 2.4 }], marks: [{ x: R.tauPF, color: c.info }, { x: R.tauDF, color: c.gold }] });
      const Ts = lin(20, 400, 120), Y = Ts.map((T) => M.tadf({ ...p, T }));
      plot(cv2, { x: [20, 400], y: [0, 1.02], xl: 'T (K)', yl: L('量子产率', 'quantum yield'), series: [{ xs: Ts, ys: Y.map((y) => y.phiPF), color: c.info, width: 2.2, label: L('瞬时', 'prompt') }, { xs: Ts, ys: Y.map((y) => y.phiDF), color: c.gold, width: 2.2, label: L('延迟', 'delayed') }, { xs: Ts, ys: Y.map((y) => y.etaEL), color: c.ok, width: 2, dash: [5, 4], label: L('电致发光内效率', 'internal EL efficiency') }], marks: [{ x: s.T, y: R.etaEL, color: c.danger }], hmarks: [{ y: 0.25, color: c.line }] });
      return [[L('反向窜越 k_RISC', 'Reverse crossing k_RISC'), `${sci(R.kRISC)} s⁻¹`], [L('瞬时荧光寿命', 'Prompt fluorescence lifetime'), time(R.tauPF)], [L('延迟荧光寿命', 'Delayed fluorescence lifetime'), time(R.tauDF)], [L('Φ 瞬时 / Φ 延迟', 'Φ prompt / Φ delayed'), `${fix(R.phiPF, 3)} / ${fix(R.phiDF, 3)}`], [L('电致发光的内量子效率', 'Internal electroluminescence efficiency'), pc(R.etaEL, 1), true], [L('出光 25 % 时的外量子效率', 'External quantum efficiency with 25 % outcoupling'), pc(0.25 * R.etaEL, 1)]];
    },
  };

  // ── 12. 光氧化还原：激发态电位 ───────────────────────────────────
  const CAT = {
    ru: { n: L('Ru(bpy)₃²⁺', 'Ru(bpy)₃²⁺'), ox: 1.29, red: -1.33, e00: 2.1 },
    ir: { n: L('fac-Ir(ppy)₃', 'fac-Ir(ppy)₃'), ox: 0.77, red: -2.19, e00: 2.5 },
  };
  DEMOS.redox = {
    title: L('光催化剂为什么又是强氧化剂又是强还原剂：激发态的电位', 'Why a photocatalyst is both a strong oxidant and a strong reductant: excited-state potentials'), kind: 'approx',
    intro: L('吸收一个光子，催化剂多了 E₀₀（约 2–3 eV）的能量。这份能量既让它更容易给出电子（激发态的氧化电位比基态负 E₀₀），也让它更想要一个电子（激发态的还原电位比基态正 E₀₀）。于是同一个 Ru(bpy)₃²⁺，基态什么都不做，激发态既能把底物氧化，也能把底物还原。选一个底物电位，看电子转移的自由能 ΔG（Rehm–Weller 式）和预计的猝灭速率。', 'Absorbing a photon gives the catalyst an extra E₀₀ (about 2–3 eV). That energy makes it easier to give an electron away (the excited-state oxidation potential is E₀₀ more negative than the ground state’s) and also hungrier for one (the excited-state reduction potential is E₀₀ more positive). So the same Ru(bpy)₃²⁺ that does nothing in the ground state can, once excited, both oxidise and reduce substrates. Pick a substrate potential and see the free energy of electron transfer ΔG (Rehm–Weller) and the expected quenching rate.'),
    sel: [['cat', L('催化剂', 'Catalyst'), [['ru', 'Ru(bpy)₃²⁺'], ['ir', 'fac-Ir(ppy)₃'], ['own', L('自己设', 'Custom')]], 'ru'], ['mode', L('底物被', 'Substrate is'), [['red', L('激发态还原（底物接受电子）', 'reduced by PC* (accepts an electron)')], ['ox', L('激发态氧化（底物给出电子）', 'oxidised by PC* (gives an electron)')]], 'ox']],
    ctl: [['ox', L('基态 E(PC⁺/PC)（V vs SCE）', 'Ground E(PC⁺/PC) (V vs SCE)'), -0.5, 2.5, 0.01, 1.29, (v) => `${v.toFixed(2)} V`], ['red', L('基态 E(PC/PC⁻)（V vs SCE）', 'Ground E(PC/PC⁻) (V vs SCE)'), -3, 0, 0.01, -1.33, (v) => `${v.toFixed(2)} V`], ['e00', L('激发能 E₀₀（eV）', 'Excitation energy E₀₀ (eV)'), 1.5, 3.5, 0.01, 2.1, (v) => `${v.toFixed(2)} eV`], ['sub', L('底物的电位（V vs SCE）', 'Substrate potential (V vs SCE)'), -3, 2.5, 0.01, 0.9, (v) => `${v.toFixed(2)} V`]],
    changed(s, k) { if ((k === 'cat' || k === '') && CAT[s.cat]) { s.ox = CAT[s.cat].ox; s.red = CAT[s.cat].red; s.e00 = CAT[s.cat].e00; } else if (['ox', 'red', 'e00'].includes(k)) s.cat = 'own'; },
    figs: [[0.75, L('电位梯子（越往下越容易被还原）：基态和激发态的四个电位，金色是底物。', 'Potential ladder (lower means more easily reduced): the four ground- and excited-state potentials, with the substrate in gold.')], [0.4, L('Rehm–Weller：猝灭速率随电子转移自由能 ΔG。放热超过约 0.3 eV 就达到扩散极限。', 'Rehm–Weller: quenching rate against the free energy of electron transfer ΔG. Beyond about 0.3 eV downhill it reaches the diffusion limit.')]],
    note: L('E(PC⁺/PC*) = E(PC⁺/PC) − E₀₀，E(PC*/PC⁻) = E(PC/PC⁻) + E₀₀，忽略库仑功项和熵。Ru(bpy)₃²⁺ 和 fac-Ir(ppy)₃ 的基态电位取自 Prier、Rankic、MacMillan 2013 年综述的表（乙腈，相对 SCE），E₀₀ 由表里激发态电位和基态电位之差得到；不同溶剂和参比会差零点几伏。Rehm–Weller 用他们 1970 年的式子：k_q = k_d /(1 + 0.25(e^{ΔG‡/k_BT} + e^{ΔG/k_BT}))，ΔG‡ = ΔG/2 + √((ΔG/2)² + ΔG‡(0)²)，k_d = 2 × 10¹⁰ M⁻¹ s⁻¹，ΔG‡(0) = 0.104 eV。它没有倒置区：双分子反应在扩散极限下观察不到 Marcus 的下降，这本身是一段有名的争论。', 'E(PC⁺/PC*) = E(PC⁺/PC) − E₀₀, E(PC*/PC⁻) = E(PC/PC⁻) + E₀₀, neglecting the Coulomb work term and entropy. The ground-state potentials of Ru(bpy)₃²⁺ and fac-Ir(ppy)₃ are from the table in the 2013 review by Prier, Rankic and MacMillan (acetonitrile, vs SCE), with E₀₀ from the difference between the excited- and ground-state potentials there; other solvents and references shift them by tenths of a volt. Rehm–Weller uses their 1970 formula: k_q = k_d /(1 + 0.25(e^{ΔG‡/k_BT} + e^{ΔG/k_BT})), ΔG‡ = ΔG/2 + √((ΔG/2)² + ΔG‡(0)²), k_d = 2 × 10¹⁰ M⁻¹ s⁻¹, ΔG‡(0) = 0.104 eV. It has no inverted region: bimolecular reactions near the diffusion limit do not show the Marcus fall-off, itself a famous debate.'),
    draw(s, [cv, cv2], c) {
      const X = M.excitedPot(s.ox, s.red, s.e00);
      // 底物被激发态氧化：底物给电子给 PC*，看 E(PC*/PC⁻) 和底物的 E(S⁺/S)：ΔG = E(S⁺/S) − E(PC*/PC⁻)
      // 底物被激发态还原：PC* 给电子给底物，ΔG = E(PC⁺/PC*) − E(S/S⁻)
      const dG = s.mode === 'ox' ? s.sub - X.redStar : X.oxStar - s.sub, kq = M.rehmWellerK(dG);
      const { ctx, w, h } = fit(cv), top = 3, bot = -3.2, Y = (E) => 16 + ((top - E) / (top - bot)) * (h - 32);
      ctx.strokeStyle = c.line; ctx.lineWidth = 1; ctx.font = font(11); ctx.fillStyle = c.muted; ctx.textAlign = 'right';
      for (let E = -3; E <= 3; E += 0.5) { ctx.beginPath(); ctx.moveTo(56, Y(E)); ctx.lineTo(w - 10, Y(E)); ctx.stroke(); ctx.fillText(`${E > 0 ? '+' : E < 0 ? '−' : ''}${Math.abs(E).toFixed(1)}`, 50, Y(E) + 4); }
      ctx.save(); ctx.translate(12, h / 2); ctx.rotate(-PI / 2); ctx.textAlign = 'center'; ctx.fillText(L('E（V vs SCE）', 'E (V vs SCE)'), 0, 0); ctx.restore();
      const bar = (x, E, col, lab, wd = 0.2) => { ctx.strokeStyle = col; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(x, Y(E)); ctx.lineTo(Math.min(x + w * wd, w - 10), Y(E)); ctx.stroke(); ctx.fillStyle = col; ctx.font = font(12, 600); ctx.textAlign = 'left'; const t = `${lab}  ${E > 0 ? '+' : '−'}${Math.abs(E).toFixed(2)} V`; ctx.fillText(t, Math.max(58, Math.min(x, w - 6 - ctx.measureText(t).width)), Y(E) - 6); };
      const xa = 70, xb = 70 + w * 0.32;
      ctx.fillStyle = c.ink; ctx.font = font(12.5, 700); ctx.textAlign = 'left'; ctx.fillText(L('基态', 'ground state'), xa, 12); ctx.fillText(L('激发态', 'excited state'), xb, 12);
      bar(xa, s.ox, c.info, 'PC⁺/PC'); bar(xa, s.red, c.info, 'PC/PC⁻');
      bar(xb, X.oxStar, c.danger, 'PC⁺/PC*'); bar(xb, X.redStar, c.danger, 'PC*/PC⁻');
      arrow(ctx, xa + w * 0.21, Y(s.ox), xb - 4, Y(X.oxStar), c.muted, 1.4); arrow(ctx, xa + w * 0.21, Y(s.red), xb - 4, Y(X.redStar), c.muted, 1.4);
      bar(70 + w * 0.64, s.sub, c.gold, s.mode === 'ox' ? L('底物 S⁺/S', 'substrate S⁺/S') : L('底物 S/S⁻', 'substrate S/S⁻'), 0.28);
      const xs = lin(-2.5, 1, 300);
      plot(cv2, { logy: true, x: [-2.5, 1], y: [2, 11], xl: 'ΔG_ET (eV)', yl: 'k_q (M⁻¹ s⁻¹)', series: [{ xs, ys: xs.map((x) => M.rehmWellerK(x)), color: c.accent, width: 2.2 }], marks: [{ x: clamp(dG, -2.5, 1), y: kq, color: c.danger }] });
      return [[L('激发态 E(PC⁺/PC*)', 'Excited E(PC⁺/PC*)'), `${fix(X.oxStar, 2)} V`], [L('激发态 E(PC*/PC⁻)', 'Excited E(PC*/PC⁻)'), `${fix(X.redStar, 2)} V`], [L('电子转移 ΔG', 'Electron transfer ΔG'), `${fix(dG, 2)} eV`, true], [L('Rehm–Weller 猝灭速率', 'Rehm–Weller quenching rate'), `${sci(kq)} M⁻¹ s⁻¹`], [L('判断', 'Verdict'), dG < -0.1 ? `<span class="pc-ok">${L('热力学上可行', 'thermodynamically feasible')}</span>` : dG < 0.1 ? L('勉强', 'marginal') : `<span class="pc-no">${L('上坡，很慢', 'uphill, slow')}</span>`]];
    },
  };

  // ── 13. Stern–Volmer ────────────────────────────────────────────
  DEMOS.sv = {
    title: L('Stern–Volmer：猝灭剂越多，光越暗；寿命长的激发态最容易被猝灭', 'Stern–Volmer: more quencher, less light; long-lived excited states are the easiest to quench'), kind: 'exact',
    intro: L('猝灭剂分子要在激发态还活着的时候撞上它。动态猝灭时 I₀/I = 1 + k_q τ₀ [Q]，直线的斜率 K_SV = k_q τ₀：寿命 1 μs 的激发态被空气里的氧气（溶液中约 2 mM）猝灭一大半，寿命 4 ns 的荧光几乎不受影响。光催化实验靠这条直线判断哪个底物在和催化剂反应。如果猝灭剂和基态分子先结合成不发光的复合物（静态猝灭），强度的直线会往上弯，但寿命不变，这是区分两种机理的办法。', 'A quencher has to hit the excited state while it is still alive. For dynamic quenching I₀/I = 1 + k_q τ₀ [Q], a straight line with slope K_SV = k_q τ₀: an excited state living 1 μs is mostly quenched by the oxygen of air (about 2 mM in solution), while 4 ns fluorescence hardly notices. Photocatalysis experiments use this line to find which substrate reacts with the catalyst. If the quencher first binds the ground-state molecule into a dark complex (static quenching) the intensity line curves upward while the lifetime does not change, which is how the two mechanisms are told apart.'),
    ctl: [['kq', 'log₁₀ k_q (M⁻¹ s⁻¹)', 7, 10.5, 0.01, 9.5, (v) => sci(e10(v))], ['tau', L('无猝灭剂时的寿命 log₁₀ τ₀（s）', 'Unquenched lifetime log₁₀ τ₀ (s)'), -9.5, -4, 0.01, -6, (v) => time(e10(v))], ['KS', L('静态结合常数 K_S（M⁻¹）', 'Static association constant K_S (M⁻¹)'), 0, 500, 1, 0, (v) => `${v.toFixed(0)} M⁻¹`], ['Qm', L('最大浓度 [Q]（mM）', 'Maximum [Q] (mM)'), 0.1, 100, 0.1, 10, (v) => `${v.toFixed(1)} mM`]],
    btn: [[L('寿命 1 μs 的金属配合物 + 氧气', '1 μs metal complex + oxygen'), { kq: 9.5, tau: -6, KS: 0, Qm: 10 }], [L('寿命 4 ns 的荧光 + 氧气', '4 ns fluorophore + oxygen'), { kq: 10.2, tau: Math.log10(4e-9), KS: 0, Qm: 10 }], [L('再加静态猝灭', 'Add static quenching'), { KS: 150 }]],
    figs: [[0.5, L('I₀/I（实线）和 τ₀/τ（虚线）随猝灭剂浓度；竖线是空气饱和溶液里的大致氧气浓度 2 mM。', 'I₀/I (solid) and τ₀/τ (dashed) against quencher concentration; the vertical line is roughly the oxygen in air-saturated solution, 2 mM.')]],
    note: L('动态：I₀/I = τ₀/τ = 1 + K_D[Q]，K_D = k_q τ₀。动态加静态：I₀/I = (1 + K_D[Q])(1 + K_S[Q])，τ₀/τ 仍是 1 + K_D[Q]。k_q 上限是扩散速率常数（水和有机溶剂里约 10¹⁰ M⁻¹ s⁻¹）。氧气在空气饱和的有机溶剂里约 1–2 mM、水里约 0.27 mM，所以竖线只是量级。', 'Dynamic: I₀/I = τ₀/τ = 1 + K_D[Q], K_D = k_q τ₀. Dynamic plus static: I₀/I = (1 + K_D[Q])(1 + K_S[Q]), while τ₀/τ stays 1 + K_D[Q]. k_q is capped by the diffusion rate constant (about 10¹⁰ M⁻¹ s⁻¹ in water and organic solvents). Oxygen in air-saturated organic solvents is about 1–2 mM and in water about 0.27 mM, so the vertical line is only an order of magnitude.'),
    draw(s, [cv], c) {
      const kq = e10(s.kq), t0 = e10(s.tau), Qm = s.Qm / 1000, qs = lin(0, Qm, 200), R = qs.map((q) => M.sternVolmer(q, kq, t0, s.KS));
      const top = Math.max(2, R[R.length - 1].I) * 1.05;
      plot(cv, { x: [0, s.Qm], y: [0, top], xl: '[Q] (mM)', yl: 'I₀/I , τ₀/τ', series: [{ xs: qs.map((q) => q * 1000), ys: R.map((r) => r.I), color: c.accent, width: 2.4, label: 'I₀/I' }, { xs: qs.map((q) => q * 1000), ys: R.map((r) => r.tau), color: c.gold, width: 2, dash: [5, 4], label: 'τ₀/τ' }], marks: s.Qm >= 2 ? [{ x: 2, color: c.muted }] : [] });
      const KD = kq * t0, air = M.sternVolmer(0.002, kq, t0, s.KS);
      return [[L('Stern–Volmer 常数 K_D = k_q τ₀', 'Stern–Volmer constant K_D = k_q τ₀'), `${fmt(KD, 3)} M⁻¹`, true], [L('猝灭一半要的浓度 1/K_D', 'Concentration for half quenching 1/K_D'), `${fmt(1000 / KD, 3)} mM`], [L('2 mM 氧气时剩下的光', 'Light left with 2 mM oxygen'), pc(1 / air.I, 1)], [L('2 mM 时的寿命', 'Lifetime at 2 mM'), time(t0 / air.tau)]];
    },
  };

  // ── 14. 自由基对 ────────────────────────────────────────────────
  DEMOS.rp = {
    title: L('自由基对：比冰箱贴弱一千倍的磁场，怎样改变一个化学反应的产率', 'Radical pairs: how a field a thousand times weaker than a fridge magnet changes a chemical yield'), kind: 'toy',
    intro: L('光引发的电子转移产生一对自由基，两个未成对电子起初是单重态。只有单重态能复合回原来的分子，三重态走另一条路。两个电子在各自的核自旋（超精细耦合）和外磁场里进动，单重态和三重态来回转换；磁场改变这种转换，于是改变了单重态产物的比例。超精细耦合是各向异性的时候，产率还和磁场的方向有关，这是鸟类磁罗盘的候选机理（隐花色素里的自由基对）。地磁场约 0.05 mT。', 'A light-driven electron transfer makes a pair of radicals whose two unpaired electrons start as a singlet. Only the singlet can recombine to the original molecule; the triplet goes another way. The two electrons precess in their nuclear spins’ fields (hyperfine coupling) and the external field, converting back and forth between singlet and triplet; a magnetic field changes that conversion, and so the share of singlet product. When the hyperfine coupling is anisotropic, the yield also depends on the field’s direction: a candidate mechanism for the avian magnetic compass (radical pairs in cryptochrome). Earth’s field is about 0.05 mT.'),
    ctl: [['a', L('超精细耦合 a（mT）', 'Hyperfine coupling a (mT)'), 0.05, 3, 0.01, 1, (v) => `${v.toFixed(2)} mT`], ['lk', L('复合速率 log₁₀ k（μs⁻¹）', 'Recombination rate log₁₀ k (μs⁻¹)'), -2, 2, 0.01, 0, (v) => `${fmt(e10(v), 3)} μs⁻¹`], ['Bm', L('横轴最大磁场（mT）', 'Maximum field shown (mT)'), 0.2, 20, 0.1, 5, (v) => `${v.toFixed(1)} mT`], ['B', L('看方向时的磁场（mT）', 'Field for the direction plot (mT)'), 0.01, 2, 0.01, 0.05, (v) => `${v.toFixed(2)} mT`]],
    chk: [['aniso', L('超精细耦合各向异性（只沿 z 轴）', 'Anisotropic hyperfine (along z only)'), true]],
    btn: [[L('地磁场下看方向', 'Direction in Earth’s field'), { B: 0.05, aniso: true, lk: -0.3 }], [L('复合太快：磁场没用', 'Recombination too fast: no field effect'), { lk: 2 }], [L('各向同性', 'Isotropic'), { aniso: false }]],
    figs: [[0.45, L('单重态产率 Φ_S 随磁场大小（磁场沿 z）。', 'Singlet yield Φ_S against field strength (field along z).')], [0.45, L('Φ_S 随磁场和 z 轴的夹角：各向异性的超精细耦合让产率随方向变，这就是“罗盘”。', 'Φ_S against the angle between field and z axis: anisotropic hyperfine coupling makes the yield direction dependent, the “compass”.')]],
    note: L('玩具模型：电子 1 带一个自旋 ½ 的核，电子 2 没有核，两个电子 g 因子相同，没有交换和偶极相互作用。8 维哈密顿量 H = γB·(S₁ + S₂) + S₁·A·I，对角化后 Φ_S = (1/2) Σₘₙ |⟨m|P_S|n⟩|² k²/(k² + ω²ₘₙ)（单重态初态、核自旋随机、两个通道同一个速率 k）。各向异性取 A = diag(0, 0, a)。真实的隐花色素自由基对有几十个核，产率随方向的变化只有百分之几到千分之几；鸟是不是真这样用，见量子生物学的“鸟类磁感应”一节。', 'Toy model: electron 1 carries one spin-½ nucleus, electron 2 none; equal g factors, no exchange or dipolar coupling. The 8-dimensional Hamiltonian H = γB·(S₁ + S₂) + S₁·A·I is diagonalised and Φ_S = (1/2) Σₘₙ |⟨m|P_S|n⟩|² k²/(k² + ω²ₘₙ) (singlet start, random nuclear spin, one rate k for both channels). The anisotropic case uses A = diag(0, 0, a). Real cryptochrome radical pairs have dozens of nuclei and a direction effect of percent to per mille; whether birds really use it is discussed in quantum biology’s section on avian magnetoreception.'),
    draw(s, [cv, cv2], c) {
      const k = e10(s.lk), aP = s.aniso ? 0 : s.a, aZ = s.a, Bs = lin(0, s.Bm, 90);
      const Y = Bs.map((B) => M.singletYield(B, 0, aP, aZ, k));
      plot(cv, { x: [0, s.Bm], y: [Math.min(...Y) - 0.03, Math.max(...Y) + 0.03], xl: 'B (mT)', yl: 'Φ_S', series: [{ xs: Bs, ys: Y, color: c.accent, width: 2.4 }], marks: [{ x: 0.05, color: c.muted }] });
      const th = lin(0, 180, 61), Yt = th.map((t) => M.singletYield(s.B, (t * PI) / 180, aP, aZ, k)), lo = Math.min(...Yt), hi = Math.max(...Yt), pad = Math.max(0.005, (hi - lo) * 0.2);
      plot(cv2, { x: [0, 180], y: [lo - pad, hi + pad], xl: L('磁场和 z 轴的夹角（°）', 'angle between field and z (°)'), yl: 'Φ_S', yf: (t) => t.toFixed(3), series: [{ xs: th, ys: Yt, color: c.gold, width: 2.4 }] });
      const y0 = M.singletYield(0, 0, aP, aZ, k), yE = M.singletYield(0.05, 0, aP, aZ, k), yH = M.singletYield(50, 0, aP, aZ, k);
      return [[L('零场 Φ_S', 'Zero-field Φ_S'), fix(y0, 4)], [L('地磁场 0.05 mT 的 Φ_S', 'Φ_S at Earth’s 0.05 mT'), fix(yE, 4)], [L('强场（50 mT）的 Φ_S', 'High-field (50 mT) Φ_S'), fix(yH, 4)], [L('随方向的变化（最大 − 最小）', 'Direction effect (max − min)'), `${fix(hi - lo, 4)} · ${pc((hi - lo) / ((hi + lo) / 2), 2)}`, true], [L('自旋进动一圈 / 寿命', 'One precession / lifetime'), fix((2 * PI) / (M.C.gammaE * s.a) * k, 3)]];
    },
  };

  // ── 15. 瞬态吸收 ────────────────────────────────────────────────
  const TA = { g: 1, lg: 470, wg: 60, se: 0.7, lse: 540, esaA: 0.9, lesaA: 650, wesa: 90, esaB: 0.7, lesaB: 400 };
  DEMOS.ta = {
    title: L('泵浦–探测：一张瞬态吸收图里的漂白、受激发射和激发态吸收', 'Pump–probe: bleach, stimulated emission and excited-state absorption in one transient-absorption map'), kind: 'toy',
    intro: L('一束飞秒泵浦光把一部分分子激发，隔一段延迟 t 再用一束宽带探测光看吸收变了多少（ΔA）。基态少了，原来的吸收带变成负的（基态漂白）；激发态会被探测光“推”着发光，也是负的（受激发射）；激发态自己还能再吸收，是正的（激发态吸收）。这里的分子先变成 A，再以 τ₁ 变成 B（比如系间窜越到三重态），B 再以 τ₂ 回到基态。调两个寿命和仪器响应，看图怎么变；横轴在 1 ps 以内是线性的，之后是对数的。', 'A femtosecond pump excites some of the molecules; after a delay t a broadband probe measures the change in absorption (ΔA). With fewer molecules in the ground state, the original absorption band turns negative (ground-state bleach); the excited state is “pushed” to emit by the probe, also negative (stimulated emission); and the excited state can absorb again, positive (excited-state absorption). Here the molecule becomes A, turns into B with τ₁ (say intersystem crossing to the triplet), and B returns to the ground state with τ₂. Change the two lifetimes and the instrument response to see the map change; the time axis is linear up to 1 ps and logarithmic after.'),
    ctl: [['t1', L('A → B 的寿命 log₁₀ τ₁（ps）', 'A → B lifetime log₁₀ τ₁ (ps)'), -1, 3, 0.01, 1, (v) => `${fmt(e10(v), 3)} ps`], ['t2', L('B → 基态的寿命 log₁₀ τ₂（ps）', 'B → ground lifetime log₁₀ τ₂ (ps)'), 0, 5, 0.01, 3, (v) => `${fmt(e10(v), 3)} ps`], ['irf', L('仪器响应半高宽（fs）', 'Instrument response FWHM (fs)'), 20, 1000, 5, 120, (v) => `${v.toFixed(0)} fs`], ['td', L('看光谱的延迟 log₁₀ t（ps）', 'Delay for the spectrum log₁₀ t (ps)'), -1, 3.5, 0.01, 0, (v) => `${fmt(e10(v), 3)} ps`], ['lp', L('看动力学的波长（nm）', 'Wavelength for the kinetics (nm)'), 350, 750, 1, 650, (v) => `${v.toFixed(0)} nm`]],
    btn: [[L('快的内转换', 'Fast internal conversion'), { t1: -0.3, t2: 1.3 }], [L('系间窜越到长寿命三重态', 'Crossing to a long-lived triplet'), { t1: 1.2, t2: 4 }], [L('仪器响应很差', 'Poor instrument response'), { irf: 800 }]],
    figs: [[0.6, L('ΔA(λ, t)：红是吸收增加，蓝是减少（漂白和受激发射）。白色虚线是下面两张图取的波长和延迟。', 'ΔA(λ, t): red is increased absorption, blue decreased (bleach and stimulated emission). The white dashed lines are the wavelength and delay used below.')], [0.4, L('选定延迟的瞬态光谱（实线）和物种光谱（虚线：A 和 B 各自减去基态）。', 'Transient spectrum at the chosen delay (solid) and the species spectra (dashed: A and B each minus the ground state).')], [0.4, L('选定波长的动力学。', 'Kinetics at the chosen wavelength.')]],
    note: L('依次反应 A → B → 基态，c_A = e^{−t/τ₁}，c_B = τ₂/(τ₂ − τ₁)(e^{−t/τ₂} − e^{−t/τ₁})，都和高斯仪器响应解析卷积（指数 ⊗ 高斯 = ½ exp(−t²/2σ²) erfcx((σ²/τ − t)/√2σ)）。ΔA = c_A(ε_A − ε_G) + c_B(ε_B − ε_G)；物种光谱是高斯，位置只是示意。真实数据还有相干伪信号、溶剂响应、振动冷却和光谱的连续移动；从数据倒推物种光谱的“全局分析和目标分析”就是这个模型的反问题。', 'Sequential A → B → ground, c_A = e^{−t/τ₁}, c_B = τ₂/(τ₂ − τ₁)(e^{−t/τ₂} − e^{−t/τ₁}), both convolved analytically with a Gaussian instrument response (exponential ⊗ Gaussian = ½ exp(−t²/2σ²) erfcx((σ²/τ − t)/√2σ)). ΔA = c_A(ε_A − ε_G) + c_B(ε_B − ε_G); the species spectra are Gaussians placed only for illustration. Real data also have coherent artefacts, solvent response, vibrational cooling and continuous spectral shifts; recovering species spectra from data, “global and target analysis”, is the inverse problem of this model.'),
    draw(s, [cv, cv2, cv3], c) {
      const k1 = 1 / e10(s.t1), k2 = 1 / e10(s.t2), sig = s.irf / 1000 / 2.3548, nl = 120, nt = 140, ls = lin(350, 750, nl);
      const U = (t) => (Math.abs(t) <= 1 ? t : Math.sign(t) * (1 + Math.log10(Math.abs(t)))), Ui = (u) => (Math.abs(u) <= 1 ? u : Math.sign(u) * 10 ** (Math.abs(u) - 1));
      const u0 = -1, u1 = 1 + 4.5, us = lin(u0, u1, nt), ts = us.map(Ui);
      const rows = ts.map((t) => ls.map((l) => M.taDelta(l, t, k1, k2, sig, TA)));
      const mx = Math.max(1e-6, ...rows.flat().map(Math.abs));
      const { ctx, w, h } = K.cells(cv, rows.slice().reverse(), (v) => { const a = clamp(Math.abs(v) / mx, 0, 1) ** 0.7; return v > 0 ? `rgba(214,58,58,${a})` : `rgba(48,104,214,${a})`; });
      ctx.setLineDash([4, 4]); ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 1.2;
      const xl = ((s.lp - 350) / 400) * w, yt = h - ((U(e10(s.td)) - u0) / (u1 - u0)) * h;
      ctx.beginPath(); ctx.moveTo(xl, 0); ctx.lineTo(xl, h); ctx.moveTo(0, yt); ctx.lineTo(w, yt); ctx.stroke(); ctx.setLineDash([]);
      ctx.font = font(11, 600); ctx.fillStyle = c.ink; ctx.textAlign = 'left';
      for (const [lab, t] of [['0', 0], ['1 ps', 1], ['10 ps', 10], ['100 ps', 100], ['1 ns', 1000], ['10 ns', 1e4]]) { const y = h - ((U(t) - u0) / (u1 - u0)) * h; if (y > 10 && y < h - 2) { ctx.fillText(lab, 4, y - 2); ctx.strokeStyle = c.line; ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(18, y); ctx.stroke(); } }
      ctx.textAlign = 'center'; for (const l of [400, 500, 600, 700]) ctx.fillText(`${l} nm`, ((l - 350) / 400) * w, h - 4);
      const td = e10(s.td), spec = ls.map((l) => M.taDelta(l, td, k1, k2, sig, TA)), sp = ls.map((l) => M.taSpectra(l, TA));
      const m2 = Math.max(...sp.map((x) => Math.max(Math.abs(x.A - x.G), Math.abs(x.B - x.G))));
      plot(cv2, { x: [350, 750], y: [-m2 * 1.1, m2 * 1.1], xl: L('波长（nm）', 'wavelength (nm)'), yl: 'ΔA', series: [{ xs: ls, ys: sp.map((x) => x.A - x.G), color: c.info, dash: [4, 4], width: 1.4, label: 'A − G' }, { xs: ls, ys: sp.map((x) => x.B - x.G), color: c.gold, dash: [4, 4], width: 1.4, label: 'B − G' }, { xs: ls, ys: spec, color: c.accent, width: 2.4, label: `t = ${fmt(td, 3)} ps` }], hmarks: [{ y: 0, color: c.line }], marks: [{ x: s.lp, color: c.muted }] });
      const kt = ts.map((t) => M.taDelta(s.lp, t, k1, k2, sig, TA)), km = Math.max(1e-6, ...kt.map(Math.abs));
      plot(cv3, { x: [u0, u1], y: [-km * 1.1, km * 1.1], xl: L('延迟（1 ps 以内线性，之后对数）', 'delay (linear to 1 ps, log after)'), xt: [-1, 0, 1, 2, 3, 4, 5], xf: (u) => (u <= 1 ? `${u}` : `${fmt(10 ** (u - 1), 2)}`), yl: 'ΔA', series: [{ xs: us, ys: kt, color: c.accent, width: 2.2 }], hmarks: [{ y: 0, color: c.line }], marks: [{ x: U(td), color: c.muted }] });
      return [[L('选定点的 ΔA', 'ΔA at the chosen point'), fmt(M.taDelta(s.lp, td, k1, k2, sig, TA), 3)], [L('这个延迟上 A、B 的布居', 'Populations of A and B at this delay'), M.seqPops(td, k1, k2, sig).map((x) => fix(x, 3)).join(' / ')], [L('仪器响应 σ', 'Instrument response σ'), `${fix(sig * 1000, 0)} fs`], [L('B 的布居最多的时刻', 'Time of maximum B'), Math.abs(k1 - k2) > 1e-9 ? `${fmt(Math.log(k1 / k2) / (k1 - k2), 3)} ps` : `${fmt(1 / k1, 3)} ps`, true]];
    },
  };
};
